/**
 * تطبيق إدارة مشروع أبناء مصطفى حسن الزراعي (القضارف - كسمور الشرقي)
 * نظام مالي وتشغيلي ومخزني متكامل
 * يحتوي على كامل سجل القيود والمصروفات الفعلية المعتمدة (182 قيد بإجمالي 130,129,000 جنيه سوداني)
 * إمكانية الدخول وصلاحيات الإدارة والتشغيل متاحة لكل من:
 * 1. محمد مصطفى (المدير العام)
 * 2. حسن مصطفى (المدير الإداري)
 * 3. مصطفى الجعلي (المدير المالي)
 * 4. عبدالقادر (الوكيل والمشرف العام على العمليات والمخزون والوقود)
 * 5. أبوبكر مصطفى (شريك في المشروع)
 */

const STORAGE_KEY = 'AGRO_MASTER_PERMANENT_DATABASE_2026_LIVE';
const SESSION_KEY = 'AGRO_SESSION_USER_MASTER';
const APP_VERSION = 'v2.2-2026-PERMANENT';

// تفعيل ميزة التخزين الدائم غير القابل للمسح من المتصفح (Persistent Storage)
if (typeof navigator !== 'undefined' && navigator.storage && navigator.storage.persist) {
  navigator.storage.persist().then(granted => {
    if (granted) console.log("✓ تم تفعيل الحفظ الدائم في المتصفح بنجاح");
  });
}

// نظام الحفظ المزدوج في IndexedDB لمنع فقدان البيانات نهائياً
const IDB_NAME = 'AgroMustafaHassanPermanentDB';
const IDB_VERSION = 1;
const IDB_STORE = 'stateStore';

function saveToIndexedDB(data) {
  try {
    if (typeof indexedDB === 'undefined') return;
    const req = indexedDB.open(IDB_NAME, IDB_VERSION);
    req.onupgradeneeded = (e) => {
      const db = e.target.result;
      if (!db.objectStoreNames.contains(IDB_STORE)) {
        db.createObjectStore(IDB_STORE, { keyPath: 'id' });
      }
    };
    req.onsuccess = (e) => {
      const db = e.target.result;
      const tx = db.transaction(IDB_STORE, 'readwrite');
      tx.objectStore(IDB_STORE).put({ id: 'master_state', data: data, timestamp: new Date().toISOString() });
    };
  } catch (err) {
    console.warn("IndexedDB save error:", err);
  }
}

