let state = loadData();
let currentUser = loadCurrentSession();

let lastSaveTime = new Date();

function showToast(message, type = 'success') {
  const container = document.getElementById('toast-container');
  if (!container) return;
  const toast = document.createElement('div');
  toast.className = `flex items-center gap-2.5 px-4 py-3 rounded-2xl shadow-xl border text-xs font-bold transition-all transform duration-300 translate-y-2 opacity-0 pointer-events-auto ${
    type === 'success' 
      ? 'bg-emerald-900 text-white border-emerald-600 shadow-emerald-950/50' 
      : (type === 'danger' ? 'bg-rose-900 text-white border-rose-600' : 'bg-slate-900 text-white border-slate-700')
  }`;
  toast.innerHTML = `
    <span class="w-6 h-6 rounded-full bg-emerald-500/20 text-emerald-300 flex items-center justify-center text-sm font-black">✓</span>
    <div>
      <p class="leading-tight text-white font-black">${message}</p>
      <span class="text-[10px] text-emerald-300/80 font-normal">تم الحفظ التلقائي في قاعدة البيانات بنجاح</span>
    </div>
  `;
  container.appendChild(toast);
  setTimeout(() => {
    toast.classList.remove('translate-y-2', 'opacity-0');
  }, 10);
  setTimeout(() => {
    toast.classList.add('opacity-0', '-translate-y-2');
    setTimeout(() => toast.remove(), 300);
  }, 3500);
}

function updateDatabaseStatusBadge() {
  const badge = document.getElementById('db-status-badge');
  if (badge) {
    const timeStr = lastSaveTime.toLocaleTimeString('ar-SD', { hour: '2-digit', minute: '2-digit' });
    badge.innerHTML = `
      <span class="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
      <span>قاعدة البيانات: متصلة ومحفوظة (${timeStr})</span>
    `;
  }
}

function loadData() {
  let loaded = null;
  const candidateKeys = [
    'AGRO_MASTER_PERMANENT_DATABASE_2026_LIVE',
    'AGRO_MASTER_PERMANENT_DATABASE',
    'AGRO_MUSTAFA_HASSAN_DATA_V22',
    'AGRO_MUSTAFA_HASSAN_DATA_V21',
    'AGRO_MUSTAFA_HASSAN_DATA_V20',
    'AGRO_MUSTAFA_HASSAN_DATA_V19',
    'AGRO_MUSTAFA_HASSAN_DATA_V18',
    'AGRO_MUSTAFA_HASSAN_DATA_V2',
    'AGRO_MUSTAFA_HASSAN_DATA_V1',
    'AGRO_MUSTAFA_HASSAN_DATA'
  ];

  try {
    for (const key of candidateKeys) {
      const raw = localStorage.getItem(key);
      if (raw) {
        try {
          const parsed = JSON.parse(raw);
          if (parsed && (parsed.partners || parsed.expenses)) {
            loaded = parsed;
            console.log("✓ تم استرجاع البيانات المحفوظة من المفتاح:", key);
            break;
          }
        } catch(e) {}
      }
    }

    if (!loaded && typeof localStorage !== 'undefined') {
      for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i);
        if (k && k.toLowerCase().includes('agro')) {
          try {
            const parsed = JSON.parse(localStorage.getItem(k));
            if (parsed && (parsed.partners || parsed.expenses)) {
              loaded = parsed;
              console.log("✓ تم استرجاع البيانات من المفتاح المستكشف:", k);
              break;
            }
          } catch(e) {}
        }
      }
    }
  } catch (e) {
    console.error("فشل قراءة الذاكرة المحلية:", e);
  }

  const def = JSON.parse(JSON.stringify(DEFAULT_DATA));
  if (!loaded) return def;

  // الحفاظ التام على تعديلات وحذف المستخدم عبر كامل التطبيق 100%
  return {
    farmInfo: { ...def.farmInfo, ...(loaded.farmInfo || {}) },
    users: Array.isArray(loaded.users) ? loaded.users : def.users,
    auditLogs: Array.isArray(loaded.auditLogs) ? loaded.auditLogs : def.auditLogs,
    plots: Array.isArray(loaded.plots) ? loaded.plots : def.plots,
    fuelSummary: loaded.fuelSummary || def.fuelSummary,
    fuelTransactions: Array.isArray(loaded.fuelTransactions) ? loaded.fuelTransactions : def.fuelTransactions,
    inventory: Array.isArray(loaded.inventory) ? loaded.inventory : def.inventory,
    inventoryTransactions: Array.isArray(loaded.inventoryTransactions) ? loaded.inventoryTransactions : def.inventoryTransactions,
    groceryTransactions: Array.isArray(loaded.groceryTransactions) ? loaded.groceryTransactions : def.groceryTransactions,
    partners: Array.isArray(loaded.partners) ? loaded.partners : def.partners,
    capitalInjections: Array.isArray(loaded.capitalInjections) ? loaded.capitalInjections : def.capitalInjections,
    harvestIntakes: Array.isArray(loaded.harvestIntakes) ? loaded.harvestIntakes : (def.harvestIntakes || []),
    cropSales: Array.isArray(loaded.cropSales) ? loaded.cropSales : (def.cropSales || []),
    zakatDeliveries: Array.isArray(loaded.zakatDeliveries) ? loaded.zakatDeliveries : (def.zakatDeliveries || []),
    machinery: Array.isArray(loaded.machinery) ? loaded.machinery : (def.machinery || []),
    machineryMaintenance: Array.isArray(loaded.machineryMaintenance) ? loaded.machineryMaintenance : (def.machineryMaintenance || []),
    labor: Array.isArray(loaded.labor) ? loaded.labor : def.labor,
    expenses: Array.isArray(loaded.expenses) ? loaded.expenses : def.expenses,
    capitalPlan: loaded.capitalPlan || def.capitalPlan,
    budgetCaps: Array.isArray(loaded.budgetCaps) ? loaded.budgetCaps : def.budgetCaps,
    forecastSettings: {
      ...def.forecastSettings,
      ...(loaded.forecastSettings || {}),
      nextSeasonAllocation: (loaded.forecastSettings && loaded.forecastSettings.nextSeasonAllocation !== undefined) ? parseFloat(loaded.forecastSettings.nextSeasonAllocation) : 500000000,
      zakatRatePercent: (loaded.forecastSettings && loaded.forecastSettings.zakatRatePercent !== undefined) ? parseFloat(loaded.forecastSettings.zakatRatePercent) : 10
    }
  };
}

function resetToLatestOfficialData() {
  if (confirm("هل تريد استعادة وتحديث قاعدة البيانات بالكامل إلى أحدث نسخة رسمية معتمدة لعام 2026؟")) {
    state = JSON.parse(JSON.stringify(DEFAULT_DATA));
    saveData("✓ تم استعادة وتحديث قاعدة البيانات بالكامل إلى أحدث نسخة معتمدة لعام 2026");
    location.reload();
  }
}

function saveData(notifyMessage = null) {
  try {
    recalculateFuelTotals();
    recalculateInventoryTotals();
    autoUpdateLaborWages();
    recalculatePartnerCapital();
    
    const stateStr = JSON.stringify(state);
    
    // 1. الحفظ في المفتاح الدائم الرئيسي
    localStorage.setItem(STORAGE_KEY, stateStr);
    
    // 2. الحفظ في مفاتيح النسخ الاحتياطي المتعددة
    localStorage.setItem('AGRO_MUSTAFA_HASSAN_DATA_V22', stateStr);
    localStorage.setItem('AGRO_MUSTAFA_HASSAN_DATA_V21', stateStr);
    localStorage.setItem('AGRO_MUSTAFA_HASSAN_DATA', stateStr);
    
    // 3. الحفظ المزدوج في IndexedDB للحماية من أي مسح
    saveToIndexedDB(state);
    
    lastSaveTime = new Date();
    updateDatabaseStatusBadge();
    updateActiveViews();
    if (notifyMessage) {
      showToast(notifyMessage);
    }
  } catch (e) {
    console.error("فشل حفظ البيانات:", e);
    showToast("خطأ: تعذر حفظ التعديلات في الذاكرة", "danger");
  }
}

function loadCurrentSession() {
  try {
    const raw = localStorage.getItem(SESSION_KEY);
    if (raw) return JSON.parse(raw);
  } catch (e) {}
  return state.users ? state.users[0] : DEFAULT_DATA.users[0];
}

function setCurrentSession(user) {
  currentUser = user;
  if (user) {
    localStorage.setItem(SESSION_KEY, JSON.stringify(user));
  } else {
    localStorage.removeItem(SESSION_KEY);
  }
  updateUserInterface();
}

function logAudit(actionType, details, target) {
  const now = new Date();
  const timestamp = now.toLocaleDateString('ar-SD', { year: 'numeric', month: 'numeric', day: 'numeric' }) + ' ' + now.toLocaleTimeString('ar-SD');
  
  const user = currentUser || { id: "guest", name: "مصطفى الجعلي", roleTitle: "المدير المالي" };

  const logEntry = {
    id: `log-${Date.now()}`,
    timestamp,
    userId: user.id,
    userName: user.name,
    userRole: user.roleTitle,
    actionType,
    details,
    target: target || "-"
  };

  if (!state.auditLogs) state.auditLogs = [];
  state.auditLogs.unshift(logEntry);
}

// إعادة احتساب إجماليات الوقود
function recalculateFuelTotals() {
  if (!state.fuelTransactions) state.fuelTransactions = [];

  let totalPurchased = 0;
  let totalConsumed = 0;

  state.fuelTransactions.forEach(tx => {
    const qty = parseFloat(tx.quantity) || 0;
    if (tx.type === 'purchase') {
      totalPurchased += qty;
    } else if (tx.type === 'issue') {
      totalConsumed += qty;
    }
  });

  state.fuelSummary = {
    purchased: totalPurchased,
    consumed: totalConsumed,
    inWarehouse: Math.max(0, totalPurchased - totalConsumed),
    unit: "برميل"
  };

  if (state.inventory) {
    const fuelInv = state.inventory.find(i => i.category === 'وقود' || i.name.includes('جاز'));
    if (fuelInv) {
      fuelInv.purchasedQty = totalPurchased;
      fuelInv.usedQty = totalConsumed;
      fuelInv.remainingQty = state.fuelSummary.inWarehouse;
    }
  }
}

// إعادة احتساب أرصدة أصناف المخزون الزراعي من واقع الحركات
function recalculateInventoryTotals() {
  if (!state.inventory) state.inventory = [];
  if (!state.inventoryTransactions) state.inventoryTransactions = [];

  state.inventory.forEach(item => {
    if (item.category === 'وقود') return;

    // إذا كان صنف محاصيل وغلال، نحسب إجمالي التشوين من دخوليات الحصاد
    if (item.category === 'محاصيل' || item.category === 'غلال') {
      const cropCat = item.name.includes('ذرة') ? 'ذرة' : 'تسالي';
      const harvestIntakesList = state.harvestIntakes || [];
      const totalHarvestBags = harvestIntakesList.filter(h => h.crop && h.crop.includes(cropCat)).reduce((sum, h) => sum + (parseFloat(h.bags) || 0), 0);
      if (totalHarvestBags > 0 || harvestIntakesList.length > 0) {
        item.purchasedQty = totalHarvestBags;
      }
    }

    const itemTx = state.inventoryTransactions.filter(t => t.itemId === item.id);
    if (itemTx.length > 0) {
      let purchaseTxSum = 0;
      let hasPurchaseTx = false;
      let used = 0;
      itemTx.forEach(t => {
        const qty = parseFloat(t.quantity) || 0;
        if (t.type === 'purchase') {
          purchaseTxSum += qty;
          hasPurchaseTx = true;
        } else if (t.type === 'issue') {
          used += qty;
        }
      });
      if (hasPurchaseTx) {
        item.purchasedQty = purchaseTxSum;
      }
      item.usedQty = used;
      item.remainingQty = Math.max(0, (item.purchasedQty || 0) - used);
    } else {
      item.remainingQty = Math.max(0, (item.purchasedQty || 0) - (item.usedQty || 0));
    }
  });
}

// احتساب مستحقات ورواتب العمالة والمشرفين تلقائياً بناءً على نوع العامل وتاريخ المباشرة وتاريخ الانتهاء ومسحوبات البقالة
function autoUpdateLaborWages() {
  if (!state.labor) return;

  const now = new Date();
  const groceryTxList = state.groceryTransactions || [];

  state.labor.forEach(w => {
    if (!w.workerType) {
      w.workerType = (w.id === 'lab-5') ? 'temporary' : 'permanent';
    }

    // احتساب إجمالي مسحوبات البقالة الآجلة للعامل
    const workerGroc = groceryTxList.filter(t => t.workerId === w.id || t.workerName === w.name);
    w.groceryTotal = workerGroc.reduce((sum, t) => sum + (parseFloat(t.amount) || 0), 0);

    // إذا كان الموظف لديه تاريخ مباشرة وراتب شهري
    if (w.startDate && w.monthlySalary > 0) {
      let calcEndDate = now;
      if (w.endDate) {
        const endD = new Date(w.endDate);
        if (!isNaN(endD.getTime())) {
          calcEndDate = (endD < now) ? endD : now;
        }
      }

      const days = Math.max(1, getDaysDiff(w.startDate, calcEndDate));
      const computedMonths = +(days / 30).toFixed(1);
      w.daysWorked = days;
      w.monthsWorked = Math.max(0.1, computedMonths);
    } else {
      w.daysWorked = Math.round((parseFloat(w.monthsWorked) || 1) * 30);
    }

    const months = parseFloat(w.monthsWorked) || 1;
    const salary = parseFloat(w.monthlySalary) || 0;
    const overtime = parseFloat(w.overtime) || 0;
    const generalDeductions = parseFloat(w.deductionsAmount) || 0;
    const groceryDeductions = parseFloat(w.groceryTotal) || 0;
    
    w.totalDeductions = generalDeductions + groceryDeductions;
    w.totalDue = Math.round(months * salary) + overtime - w.totalDeductions;
    w.status = (w.totalPaid || 0) >= w.totalDue ? 'paid' : ((w.totalPaid || 0) > 0 ? 'partial' : 'pending');
  });
}

