function calculateMetrics() {
  const totalArea = state.farmInfo.totalArea;
  
  let sorghumArea = 0;
  let tasaliArea = 0;
  let totalPlanted = 0;
  let totalPrepared = 0;

  state.plots.forEach(plot => {
    if (plot.crop.includes("ذرة")) sorghumArea += plot.area;
    else if (plot.crop.includes("تسالي")) tasaliArea += plot.area;
    totalPlanted += (plot.plantedFeddans || 0);
    totalPrepared += (plot.prepFeddans || 0);
  });

  let totalExpenses = 0;
  let sorghumExpenses = 0;
  let tasaliExpenses = 0;
  let sharedExpenses = 0;
  let homeExpenses = 0;
  const categoryTotals = {};

  state.expenses.forEach(exp => {
    const amt = parseFloat(exp.amount) || 0;
    totalExpenses += amt;
    categoryTotals[exp.category] = (categoryTotals[exp.category] || 0) + amt;

    if (exp.crop === "ذرة") {
      sorghumExpenses += amt;
    } else if (exp.crop === "تسالي") {
      tasaliExpenses += amt;
    } else if (exp.crop === "البيت") {
      homeExpenses += amt;
    } else {
      sharedExpenses += amt;
    }
  });

  const sorghumRatio = sorghumArea / (totalArea || 1);
  const tasaliRatio = tasaliArea / (totalArea || 1);

  const effectiveSorghumExpense = sorghumExpenses + (sharedExpenses * sorghumRatio);
  const effectiveTasaliExpense = tasaliExpenses + (sharedExpenses * tasaliRatio);

  const costPerFeddanSorghum = sorghumArea > 0 ? (effectiveSorghumExpense / sorghumArea) : 0;
  const costPerFeddanTasali = tasaliArea > 0 ? (effectiveTasaliExpense / tasaliArea) : 0;
  const overallCostPerFeddan = totalArea > 0 ? ((totalExpenses - homeExpenses) / totalArea) : 0;

  return {
    totalArea,
    sorghumArea,
    tasaliArea,
    totalPlanted,
    totalPrepared,
    totalExpenses,
    homeExpenses,
    farmExpenses: totalExpenses - homeExpenses,
    sorghumExpenses: effectiveSorghumExpense,
    tasaliExpenses: effectiveTasaliExpense,
    costPerFeddanSorghum,
    costPerFeddanTasali,
    overallCostPerFeddan,
    categoryTotals,
    fuelInStock: state.fuelSummary.inWarehouse,
    fuelUsed: state.fuelSummary.consumed
  };
}

function renderHeaderKPIs() {
  const m = calculateMetrics();
  
  const elTotalArea = document.getElementById('kpi-total-area');
  const elTotalSpent = document.getElementById('kpi-total-spent');
  const elSorghumCost = document.getElementById('kpi-sorghum-cost');
  const elTasaliCost = document.getElementById('kpi-tasali-cost');
  const elFuelStock = document.getElementById('kpi-fuel-stock');
  const elOverallProgress = document.getElementById('kpi-overall-progress');

  if (elTotalArea) elTotalArea.innerText = `${m.totalArea.toLocaleString()} فدان`;
  if (elTotalSpent) elTotalSpent.innerText = `${m.totalExpenses.toLocaleString()} جنيه`;
  if (elSorghumCost) elSorghumCost.innerText = `${Math.round(m.costPerFeddanSorghum).toLocaleString()} ج/فدان`;
  if (elTasaliCost) elTasaliCost.innerText = `${Math.round(m.costPerFeddanTasali).toLocaleString()} ج/فدان`;
  if (elFuelStock) elFuelStock.innerText = `${m.fuelInStock} برميل متبقي`;
  
  const progressPercent = Math.round((m.totalPlanted / m.totalArea) * 100) || 0;
  if (elOverallProgress) {
    elOverallProgress.innerHTML = `
      <div class="flex justify-between text-[10px] mb-1 font-bold">
        <span>الزراعة المنجزة: ${progressPercent}%</span>
        <span>${m.totalPlanted} فدان</span>
      </div>
      <div class="w-full bg-slate-200 dark:bg-slate-700 h-2 rounded-full overflow-hidden">
        <div class="bg-emerald-400 h-2 rounded-full transition-all duration-500" style="width: ${progressPercent}%"></div>
      </div>
    `;
  }
}

function renderFarmVisualMap() {
  const container = document.getElementById('farm-visual-map');
  if (!container) return;

  container.innerHTML = state.plots.map(plot => {
    const isPlanted = (plot.plantedFeddans || 0) >= plot.area;
    const isPrep = (plot.prepFeddans || 0) > 0 && !isPlanted;
    
    let bgStyle = 'bg-slate-100 border-slate-300 dark:bg-slate-800 dark:border-slate-700';
    let statusText = 'مخطط زراعة 25/09';
    let statusBadgeColor = 'bg-slate-200 text-slate-700';

    if (isPlanted) {
      bgStyle = 'bg-emerald-50 border-emerald-400 dark:bg-emerald-950/40 dark:border-emerald-700';
      statusText = '✓ تم الحراثة والزراعة';
      statusBadgeColor = 'bg-emerald-100 text-emerald-800 font-bold';
    } else if (isPrep) {
      bgStyle = 'bg-amber-50 border-amber-400 dark:bg-amber-950/40 dark:border-amber-700';
      statusText = '🚜 تجهيز / كسرة أولى';
      statusBadgeColor = 'bg-amber-100 text-amber-800 font-bold';
    }

    return `
      <div onclick="openPlotDetailsModal('${plot.id}')" class="plot-map-item p-4 rounded-2xl border-2 ${bgStyle} flex flex-col justify-between shadow-sm cursor-pointer hover:scale-[1.02] transition" title="اضغط لعرض تفاصيل ومصروفات وعمليات النمرة">
        <div>
          <div class="flex justify-between items-start mb-1">
            <h4 class="font-black text-sm text-slate-900 dark:text-white">📍 ${plot.name}</h4>
            <span class="text-[10px] px-2 py-0.5 rounded-full ${statusBadgeColor}">${plot.crop}</span>
          </div>
          <p class="text-xs font-black text-slate-700 dark:text-slate-300 mt-1">${plot.area} فدان</p>
        </div>
        <div class="mt-3 pt-2 border-t border-slate-200/60 dark:border-slate-700/60 flex items-center justify-between text-[11px]">
          <span class="text-slate-600 dark:text-slate-400 font-medium">${statusText}</span>
          <span class="text-emerald-600 font-bold">تفاصيل 🔍</span>
        </div>
      </div>
    `;
  }).join('');
}

function renderCharts() {
  if (typeof Chart === 'undefined') return;

  const m = calculateMetrics();
  const isDark = document.body.classList.contains('dark-mode');
  const textColor = isDark ? '#e2e8f0' : '#1e293b';

  const ctxCategory = document.getElementById('expensesCategoryChart');
  if (ctxCategory) {
    const categories = Object.keys(m.categoryTotals);
    const amounts = Object.values(m.categoryTotals);

    if (categoryChartInstance) categoryChartInstance.destroy();

    categoryChartInstance = new Chart(ctxCategory, {
      type: 'doughnut',
      data: {
        labels: categories.length > 0 ? categories : ['لا توجد مصروفات'],
        datasets: [{
          data: amounts.length > 0 ? amounts : [1],
          backgroundColor: [
            '#10b981', '#f59e0b', '#3b82f6', '#ec4899', '#8b5cf6', '#14b8a6', '#64748b', '#ef4444', '#06b6d4', '#a855f7'
          ],
          borderWidth: 2,
          borderColor: isDark ? '#142419' : '#ffffff'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            position: 'right',
            labels: {
              color: textColor,
              font: { family: 'Cairo', size: 10 }
            }
          }
        }
      }
    });
  }

  const ctxComparison = document.getElementById('cropsComparisonChart');
  if (ctxComparison) {
    if (comparisonChartInstance) comparisonChartInstance.destroy();

    comparisonChartInstance = new Chart(ctxComparison, {
      type: 'bar',
      data: {
        labels: ['ذرة ارفع قدمك محسن (959 فدان)', 'تسالي (490 فدان)'],
        datasets: [
          {
            label: 'تكلفة الفدان التقديرية (جنيه/فدان)',
            data: [Math.round(m.costPerFeddanSorghum), Math.round(m.costPerFeddanTasali)],
            backgroundColor: '#10b981',
            borderRadius: 8
          },
          {
            label: 'المساحة المزروعة (فدان)',
            data: [
              state.plots.filter(p => p.crop.includes('ذرة')).reduce((acc, p) => acc + (p.plantedFeddans || 0), 0),
              state.plots.filter(p => p.crop.includes('تسالي')).reduce((acc, p) => acc + (p.plantedFeddans || 0), 0)
            ],
            backgroundColor: '#f59e0b',
            borderRadius: 8
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            labels: {
              color: textColor,
              font: { family: 'Cairo', size: 11 }
            }
          }
        },
        scales: {
          x: {
            ticks: { color: textColor, font: { family: 'Cairo' } },
            grid: { display: false }
          },
          y: {
            ticks: { color: textColor, font: { family: 'Cairo' } },
            grid: { color: isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.05)' }
          }
        }
      }
    });
  }
}

function renderPlotsDashboard() {
  const container = document.getElementById('plots-container');
  if (!container) return;

  container.innerHTML = state.plots.map(plot => {
    const isSorghum = plot.crop.includes('ذرة');
    const badgeColor = isSorghum ? 'bg-amber-100 text-amber-900 border-amber-300' : 'bg-emerald-100 text-emerald-900 border-emerald-300';
    const percentPlanted = Math.round(((plot.plantedFeddans || 0) / plot.area) * 100);
    const percentPrep = Math.round(((plot.prepFeddans || 0) / plot.area) * 100);
    const cropImg = isSorghum ? GEDAREF_IMAGES.sorghum : GEDAREF_IMAGES.tasali;

    const opsListHtml = (plot.operations || []).map(op => {
      let statusBadge = '';
      if (op.status === 'completed') statusBadge = '<span class="badge-completed text-[11px] px-2 py-0.5 rounded-full font-bold">مكتملة</span>';
      else if (op.status === 'in_progress') statusBadge = '<span class="badge-progress text-[11px] px-2 py-0.5 rounded-full font-bold">قيد التنفيذ</span>';
      else statusBadge = '<span class="badge-planned text-[11px] px-2 py-0.5 rounded-full font-bold">مخططة</span>';

      const opFeddans = parseFloat(op.areaFeddan) || plot.area;
      const opHours = op.fieldHours ? op.fieldHours : calculateFieldHours(opFeddans);

      return `
        <div class="flex items-center justify-between text-xs py-1.5 border-b border-slate-100 dark:border-slate-800 last:border-none">
          <div>
            <span class="font-bold text-slate-800 dark:text-slate-200">${op.type}</span>
            <span class="text-slate-500 mr-1.5 text-[11px]">(${op.date})</span>
            ${op.driver ? `<span class="text-emerald-700 dark:text-emerald-400 mr-1 font-semibold">🚜 ${op.driver}</span>` : ''}
            <span class="text-blue-600 dark:text-blue-400 mr-1 text-[10px] font-bold">⏱️ ${opHours} س (${opFeddans} ف @ 5 ف/س)</span>
          </div>
          <div class="flex items-center gap-2">
            ${op.fuelBarrels ? `<span class="text-slate-500 text-[11px]">⛽ ${op.fuelBarrels} برميل</span>` : ''}
            ${statusBadge}
          </div>
        </div>
      `;
    }).join('');

    return `
      <div class="glass-card rounded-2xl p-5 border border-slate-200 dark:border-slate-800 flex flex-col justify-between overflow-hidden shadow-md">
        <div>
          <!-- صورة المحصول التوضيحية من القضارف -->
          <div class="relative h-28 rounded-xl overflow-hidden mb-3.5 border border-slate-200 dark:border-slate-700 shadow-inner">
            <img src="${cropImg}" alt="${plot.crop}" class="w-full h-full object-cover transition-transform duration-700 hover:scale-105">
            <div class="absolute inset-0 bg-gradient-to-t from-slate-950/80 via-slate-950/25 to-transparent"></div>
            <div class="absolute bottom-2 right-2.5 left-2.5 flex justify-between items-center text-white">
              <span class="text-xs font-black drop-shadow flex items-center gap-1">
                <span>📍 مقطوعية ${plot.name}</span>
              </span>
              <span class="text-[11px] font-bold bg-black/50 backdrop-blur-md px-2 py-0.5 rounded-md border border-white/20">
                ${plot.area} فدان
              </span>
            </div>
          </div>

          <div class="flex items-start justify-between mb-2">
            <div>
              <p class="text-xs text-slate-500 dark:text-slate-400">المحصول المعتمد:</p>
              <h4 class="text-sm font-black text-slate-900 dark:text-white">${plot.crop}</h4>
            </div>
            <span class="text-xs font-bold px-2.5 py-0.5 rounded-full border ${badgeColor}">
              🌾 ${plot.crop}
            </span>
          </div>

          <div class="space-y-2 my-3.5 bg-slate-50 dark:bg-slate-800/60 p-3 rounded-xl">
            <div>
              <div class="flex justify-between text-xs font-semibold mb-1">
                <span class="text-slate-600 dark:text-slate-300">تجهيز الأرض / الحراثة:</span>
                <span class="text-emerald-700 dark:text-emerald-400 font-bold">${plot.prepFeddans || 0} / ${plot.area} فدان (${percentPrep}%)</span>
              </div>
              <div class="w-full bg-slate-200 dark:bg-slate-700 h-2 rounded-full overflow-hidden">
                <div class="bg-amber-500 h-2 rounded-full" style="width: ${percentPrep}%"></div>
              </div>
            </div>
            
            <div>
              <div class="flex justify-between text-xs font-semibold mb-1">
                <span class="text-slate-600 dark:text-slate-300">الزراعة الفعلية:</span>
                <span class="text-emerald-700 dark:text-emerald-400 font-bold">${plot.plantedFeddans || 0} / ${plot.area} فدان (${percentPlanted}%)</span>
              </div>
              <div class="w-full bg-slate-200 dark:bg-slate-700 h-2 rounded-full overflow-hidden">
                <div class="bg-emerald-600 h-2 rounded-full" style="width: ${percentPlanted}%"></div>
              </div>
            </div>
            <p class="text-[11px] text-slate-500 dark:text-slate-400 pt-1">
              🗓️ موعد الزراعة المتوقع: <strong class="text-slate-700 dark:text-slate-300">${plot.targetSowingDate}</strong>
            </p>
          </div>

          <div class="mb-4">
            <h4 class="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mb-2">سجل العمليات والكسرات:</h4>
            <div class="space-y-0.5 bg-white dark:bg-slate-900/80 p-2.5 rounded-xl border border-slate-100 dark:border-slate-800 max-h-32 overflow-y-auto">
              ${opsListHtml || '<p class="text-xs text-slate-400 text-center py-2">لا توجد عمليات مسجلة حتى الآن</p>'}
            </div>
          </div>
        </div>

        <div class="flex gap-2 pt-3 border-t border-slate-100 dark:border-slate-800">
          <button onclick="openAddOperationModal('${plot.id}')" class="flex-1 py-2 px-3 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl text-xs font-bold transition flex items-center justify-center gap-1.5 shadow-sm">
            <i data-lucide="plus-circle" class="w-4 h-4"></i>
            <span>إضافة عملية</span>
          </button>
          <button onclick="openEditPlotModal('${plot.id}')" class="py-2 px-3 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-300 rounded-xl text-xs font-bold transition">
            <i data-lucide="edit-3" class="w-4 h-4"></i>
          </button>
        </div>
      </div>
    `;
  }).join('');
}

function filterExpenses() {
  const query = (document.getElementById('expense-search-input')?.value || '').toLowerCase();
  const categoryFilter = document.getElementById('expense-filter-category')?.value || 'all';
  const cropFilter = document.getElementById('expense-filter-crop')?.value || 'all';
  const statusFilter = document.getElementById('expense-filter-status')?.value || 'all';

  const filtered = state.expenses.filter(exp => {
    const matchQuery = !query || 
      (exp.notes && exp.notes.toLowerCase().includes(query)) ||
      (exp.category && exp.category.toLowerCase().includes(query)) ||
      (exp.plot && exp.plot.toLowerCase().includes(query));
    
    const matchCategory = categoryFilter === 'all' || exp.category === categoryFilter;
    const matchCrop = cropFilter === 'all' || exp.crop === cropFilter;
    const matchStatus = statusFilter === 'all' || 
      (statusFilter === 'review' && exp.isUnderReview) || 
      (statusFilter === 'approved' && !exp.isUnderReview);

    return matchQuery && matchCategory && matchCrop && matchStatus;
  });

  renderExpensesTable(filtered);
}

function renderExpensesSection() {
  filterExpenses();
  renderBudgetCaps();
}

function renderExpensesTable(expensesList) {
  const tableBody = document.getElementById('expenses-table-body');
  const reviewNotice = document.getElementById('review-alert-banner');
  if (!tableBody) return;

  const reviewCount = state.expenses.filter(e => e.isUnderReview).length;
  if (reviewNotice) {
    if (reviewCount > 0) {
      reviewNotice.classList.remove('hidden');
      reviewNotice.innerHTML = `
        <div class="flex items-center justify-between p-4 bg-amber-50 dark:bg-amber-950/40 border border-amber-200 dark:border-amber-900 rounded-2xl text-amber-900 dark:text-amber-200">
          <div class="flex items-center gap-3">
            <i data-lucide="alert-triangle" class="w-6 h-6 text-amber-600"></i>
            <div>
              <p class="font-bold text-sm">تنبيه تدقيق: يوجد (${reviewCount}) قيود مصروفات مبدئية مسجلة وتحتاج إلى مراجعة وتأكيد من الإدارة المالية.</p>
              <p class="text-xs text-amber-700 dark:text-amber-300 mt-0.5">يمكن للمدير المالي (مصطفى الجعلي) أو المدير الإداري (حسن مصطفى) تعديل المبالغ أو اعتمادها فوراً.</p>
            </div>
          </div>
          <button onclick="markAllExpensesApproved()" class="text-xs bg-amber-600 hover:bg-amber-700 text-white font-bold py-1.5 px-3.5 rounded-xl shadow-sm transition">
            اعتماد وتأكيد الكل
          </button>
        </div>
      `;
    } else {
      reviewNotice.classList.add('hidden');
    }
  }

  tableBody.innerHTML = expensesList.map(exp => {
    let cropBadge = '';
    if (exp.crop === 'ذرة') {
      cropBadge = '<span class="font-semibold text-amber-700 dark:text-amber-400 bg-amber-50 dark:bg-amber-950/60 px-2 py-0.5 rounded-md">🌽 ذرة</span>';
    } else if (exp.crop === 'تسالي') {
      cropBadge = '<span class="font-semibold text-emerald-700 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-950/60 px-2 py-0.5 rounded-md">🌱 تسالي</span>';
    } else if (exp.crop === 'البيت') {
      cropBadge = '<span class="font-black text-purple-700 dark:text-purple-400 bg-purple-50 dark:bg-purple-950/60 px-2.5 py-0.5 rounded-md border border-purple-200 dark:border-purple-800">🏠 البيت</span>';
    } else {
      cropBadge = '<span class="font-medium text-slate-600 dark:text-slate-400 bg-slate-100 dark:bg-slate-800 px-2 py-0.5 rounded-md">🌾 مشترك</span>';
    }

    return `
      <tr class="border-b border-slate-100 dark:border-slate-800 hover:bg-slate-50 dark:hover:bg-slate-800/50 transition text-xs">
        <td class="py-3.5 px-4 font-mono font-medium text-slate-700 dark:text-slate-300">${exp.date}</td>
        <td class="py-3.5 px-4">
          <span class="font-bold text-slate-900 dark:text-white px-2.5 py-1 rounded-lg bg-slate-100 dark:bg-slate-800">
            ${exp.category}
          </span>
        </td>
        <td class="py-3.5 px-4 font-black text-sm text-slate-900 dark:text-white font-mono">
          ${parseFloat(exp.amount).toLocaleString()} <span class="text-[11px] font-normal text-slate-500">ج.س</span>
        </td>
        <td class="py-3.5 px-4 text-slate-600 dark:text-slate-300">${exp.plot || '-'}</td>
        <td class="py-3.5 px-4">
          ${cropBadge}
        </td>
        <td class="py-3.5 px-4 text-slate-500 max-w-xs">
          <div class="font-semibold text-slate-800 dark:text-slate-200">${exp.notes || exp.op || '-'}</div>
          <div class="text-[10px] text-slate-400 mt-0.5">
            بواسطة: <strong class="text-slate-600 dark:text-slate-400">${exp.createdBy || 'مصطفى الجعلي'}</strong>
            ${exp.modifiedBy ? ` • آخر تعديل: <span class="text-amber-600 font-semibold">${exp.modifiedBy}</span>` : ''}
          </div>
        </td>
        <td class="py-3.5 px-4">
          ${exp.isUnderReview 
            ? '<span class="badge-review text-[11px] font-bold px-2 py-0.5 rounded-full inline-flex items-center gap-1">⚠️ للمراجعة</span>' 
            : '<span class="badge-completed text-[11px] font-bold px-2 py-0.5 rounded-full inline-flex items-center gap-1">✓ معتمد</span>'}
        </td>
        <td class="py-3.5 px-4 text-left">
          <div class="flex items-center justify-end gap-1.5">
            <button onclick="openEditExpenseModal('${exp.id}')" class="p-1.5 bg-slate-100 dark:bg-slate-800 hover:bg-emerald-50 hover:text-emerald-700 rounded-lg text-slate-600 dark:text-slate-300 transition" title="تعديل وتدقيق">
              <i data-lucide="edit" class="w-4 h-4"></i>
            </button>
            <button onclick="deleteExpense('${exp.id}')" class="p-1.5 bg-slate-100 dark:bg-slate-800 hover:bg-rose-50 hover:text-rose-600 rounded-lg text-slate-600 dark:text-slate-300 transition" title="حذف">
              <i data-lucide="trash-2" class="w-4 h-4"></i>
            </button>
          </div>
        </td>
      </tr>
    `;
  }).join('');
}

function renderBudgetCaps() {
  const m = calculateMetrics();
  const budgetList = document.getElementById('budget-caps-list');
  if (!budgetList) return;

  const totalCapital = state.capitalPlan ? state.capitalPlan.totalCapital : 300000000;
  const cultivationBudget = state.capitalPlan ? state.capitalPlan.cultivationBudget : 200000000;
  const harvestBudget = state.capitalPlan ? state.capitalPlan.harvestBudget : 100000000;

  const cultivationItems = state.budgetCaps.filter(b => b.phase === 'cultivation' || !b.phase);
  const harvestItems = state.budgetCaps.filter(b => b.phase === 'harvest');

  let cultivationSpent = 0;
  cultivationItems.forEach(b => {
    cultivationSpent += getCategorySpentAmount(b.category, m.categoryTotals);
  });
  // Or cultivationSpent equals totalExpenses
  cultivationSpent = m.totalExpenses;
  const cultivationRemaining = Math.max(0, cultivationBudget - cultivationSpent);
  const cultivationPercent = Math.min(100, Math.round((cultivationSpent / cultivationBudget) * 100));

  let harvestSpent = 0;
  harvestItems.forEach(b => {
    harvestSpent += getCategorySpentAmount(b.category, m.categoryTotals);
  });
  const harvestRemaining = Math.max(0, harvestBudget - harvestSpent);
  const harvestPercent = Math.round((harvestSpent / harvestBudget) * 100);

  const totalRemainingCapital = totalCapital - (cultivationSpent + harvestSpent);
  const totalCapitalUsedPercent = Math.round(((cultivationSpent + harvestSpent) / totalCapital) * 100);

  budgetList.innerHTML = `
    <!-- ملخص مرحلتي رأس المال (300 مليون) -->
    <div class="col-span-full grid grid-cols-1 md:grid-cols-3 gap-3.5 mb-2">
      
      <!-- بطاقة رأس المال الكلي -->
      <div class="p-4 rounded-2xl bg-gradient-to-br from-slate-900 to-slate-800 text-white border border-slate-700 shadow-md">
        <div class="flex justify-between items-start mb-2">
          <div>
            <span class="text-[10px] text-emerald-400 font-bold px-2 py-0.5 bg-emerald-950/80 rounded-full">💼 رأس المال الكلي للمشروع</span>
            <h4 class="text-xl font-black font-mono mt-1">${totalCapital.toLocaleString()} <span class="text-xs font-normal text-slate-400">ج.س</span></h4>
          </div>
          <span class="text-xs bg-slate-700 text-slate-200 px-2 py-0.5 rounded-lg font-bold">100%</span>
        </div>
        <div class="space-y-1.5 text-xs text-slate-300 pt-1 border-t border-slate-700/60">
          <div class="flex justify-between"><span>المنصرف الكلي حتى الآن:</span><strong class="text-rose-400 font-mono">${(cultivationSpent + harvestSpent).toLocaleString()} ج.س</strong></div>
          <div class="flex justify-between"><span>الرصيد المالي المتبقي:</span><strong class="text-emerald-400 font-mono font-bold">${totalRemainingCapital.toLocaleString()} ج.س</strong></div>
        </div>
        <div class="w-full bg-slate-700 h-2 rounded-full overflow-hidden mt-3">
          <div class="bg-emerald-500 h-2 rounded-full transition-all duration-500" style="width: ${totalCapitalUsedPercent}%"></div>
        </div>
      </div>

      <!-- بطاقة مرحلة الزراعة والعمليات (200 مليون) -->
      <div class="p-4 rounded-2xl bg-gradient-to-br from-emerald-950 to-slate-900 text-white border border-emerald-800/60 shadow-md">
        <div class="flex justify-between items-start mb-2">
          <div>
            <span class="text-[10px] text-emerald-300 font-bold px-2 py-0.5 bg-emerald-900/60 rounded-full">🌱 ميزانية مرحلة الزراعة</span>
            <h4 class="text-xl font-black font-mono text-emerald-300 mt-1">${cultivationBudget.toLocaleString()} <span class="text-xs font-normal text-slate-300">ج.س</span></h4>
          </div>
          <span class="text-xs bg-emerald-800 text-emerald-200 px-2 py-0.5 rounded-lg font-bold">${cultivationPercent}%</span>
        </div>
        <div class="space-y-1.5 text-xs text-slate-300 pt-1 border-t border-emerald-800/40">
          <div class="flex justify-between"><span>المنصرف الفعلي للزراعة:</span><strong class="text-amber-300 font-mono">${cultivationSpent.toLocaleString()} ج.س</strong></div>
          <div class="flex justify-between"><span>المتبقي لمرحلة الزراعة:</span><strong class="text-emerald-300 font-mono font-bold">${cultivationRemaining.toLocaleString()} ج.س</strong></div>
        </div>
        <div class="w-full bg-emerald-950 h-2 rounded-full overflow-hidden mt-3">
          <div class="bg-emerald-400 h-2 rounded-full transition-all duration-500" style="width: ${cultivationPercent}%"></div>
        </div>
      </div>

      <!-- بطاقة مرحلة الحصاد والتسويق (100 مليون) -->
      <div class="p-4 rounded-2xl bg-gradient-to-br from-amber-950 to-slate-900 text-white border border-amber-800/60 shadow-md">
        <div class="flex justify-between items-start mb-2">
          <div>
            <span class="text-[10px] text-amber-300 font-bold px-2 py-0.5 bg-amber-900/60 rounded-full">🌾 ميزانية مرحلة الحصاد</span>
            <h4 class="text-xl font-black font-mono text-amber-300 mt-1">${harvestBudget.toLocaleString()} <span class="text-xs font-normal text-slate-300">ج.س</span></h4>
          </div>
          <span class="text-xs bg-amber-800 text-amber-200 px-2 py-0.5 rounded-lg font-bold">${harvestPercent}%</span>
        </div>
        <div class="space-y-1.5 text-xs text-slate-300 pt-1 border-t border-amber-800/40">
          <div class="flex justify-between"><span>المنصرف الفعلي للحصاد:</span><strong class="text-slate-300 font-mono">${harvestSpent.toLocaleString()} ج.س</strong></div>
          <div class="flex justify-between"><span>المبلغ المتاح للحصاد:</span><strong class="text-amber-300 font-mono font-bold">${harvestRemaining.toLocaleString()} ج.س</strong></div>
        </div>
        <div class="w-full bg-amber-950 h-2 rounded-full overflow-hidden mt-3">
          <div class="bg-amber-400 h-2 rounded-full transition-all duration-500" style="width: ${Math.max(harvestPercent, 5)}%"></div>
        </div>
      </div>

    </div>

    <!-- عنوان بنود مرحلة الزراعة (200 مليون) -->
    <div class="col-span-full mt-2 mb-1 flex items-center justify-between border-b border-slate-200 dark:border-slate-800 pb-1.5">
      <span class="text-xs font-black text-slate-800 dark:text-slate-200 flex items-center gap-1.5">
        <span>🌱 بنود مرحلة الزراعة والتشغيل الميداني (سقف: 200,000,000 ج.س)</span>
      </span>
      <span class="text-[11px] text-emerald-600 dark:text-emerald-400 font-bold">منصرف: ${cultivationSpent.toLocaleString()} ج.س</span>
    </div>

    ${cultivationItems.map(b => {
      const spent = getCategorySpentAmount(b.category, m.categoryTotals);
      const percent = Math.round((spent / b.cap) * 100);
      let barColor = 'bg-emerald-500';
      let textColor = 'text-emerald-600';
      
      if (percent >= 100) {
        barColor = 'bg-rose-600';
        textColor = 'text-rose-600 font-bold';
      } else if (percent >= b.warningThreshold) {
        barColor = 'bg-amber-500';
        textColor = 'text-amber-600 font-bold';
      }

      return `
        <div class="bg-white dark:bg-slate-900 p-3.5 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm">
          <div class="flex items-center justify-between text-xs mb-1.5">
            <span class="font-bold text-slate-800 dark:text-slate-200">${b.category}</span>
            <span class="${textColor} font-mono">${spent.toLocaleString()} / ${b.cap.toLocaleString()} (${percent}%)</span>
          </div>
          <div class="w-full bg-slate-100 dark:bg-slate-800 h-2 rounded-full overflow-hidden">
            <div class="${barColor} h-2 rounded-full transition-all duration-300" style="width: ${Math.min(percent, 100)}%"></div>
          </div>
        </div>
      `;
    }).join('')}

    <!-- عنوان بنود مرحلة الحصاد (100 مليون) -->
    <div class="col-span-full mt-4 mb-1 flex items-center justify-between border-b border-slate-200 dark:border-slate-800 pb-1.5">
      <span class="text-xs font-black text-slate-800 dark:text-slate-200 flex items-center gap-1.5">
        <span>🌾 بنود مرحلة الحصاد والتسويق (ميزانية معتمدة: 100,000,000 ج.س)</span>
      </span>
      <span class="text-[11px] text-amber-600 dark:text-amber-400 font-bold">متاح بالكامل: 100,000,000 ج.س</span>
    </div>

    ${harvestItems.map(b => {
      const spent = getCategorySpentAmount(b.category, m.categoryTotals);
      const percent = Math.round((spent / b.cap) * 100);
      let barColor = 'bg-amber-500';
      let textColor = 'text-amber-600';

      return `
        <div class="bg-amber-50/40 dark:bg-amber-950/20 p-3.5 rounded-xl border border-amber-200 dark:border-amber-900/40 shadow-sm">
          <div class="flex items-center justify-between text-xs mb-1.5">
            <span class="font-bold text-slate-800 dark:text-slate-200">${b.category}</span>
            <span class="${textColor} font-mono">${spent.toLocaleString()} / ${b.cap.toLocaleString()} (${percent}%)</span>
          </div>
          <div class="w-full bg-amber-100 dark:bg-slate-800 h-2 rounded-full overflow-hidden">
            <div class="${barColor} h-2 rounded-full transition-all duration-300" style="width: ${Math.min(percent, 100)}%"></div>
          </div>
        </div>
      `;
    }).join('')}
  `;
}

// عرض وإدارة حركة مخزون الوقود
function renderFuelSection() {
  const fuelCards = document.getElementById('fuel-status-cards');
  const fuelTable = document.getElementById('fuel-transactions-table');
  const filterType = document.getElementById('fuel-filter-type')?.value || 'all';
  if (!fuelCards) return;

  recalculateFuelTotals();
  const f = state.fuelSummary;
  const remainingPercent = f.purchased > 0 ? Math.round((f.inWarehouse / f.purchased) * 100) : 0;

  fuelCards.innerHTML = `
    <div class="glass-card p-5 rounded-2xl border border-slate-200 dark:border-slate-800">
      <div class="flex justify-between items-start">
        <p class="text-xs font-bold text-slate-500">إجمالي الوقود المشترى</p>
        <span class="text-[10px] bg-emerald-100 text-emerald-800 dark:bg-emerald-950 dark:text-emerald-300 px-2 py-0.5 rounded-full font-bold">📥 توريد كلي</span>
      </div>
      <p class="text-3xl font-black text-slate-900 dark:text-white mt-1">${f.purchased} <span class="text-sm font-semibold text-slate-500">برميل</span></p>
      <p class="text-xs text-slate-400 mt-1">ما يعادل ${(f.purchased * 200).toLocaleString()} لتر جازولين</p>
    </div>
    
    <div class="glass-card p-5 rounded-2xl border border-slate-200 dark:border-slate-800">
      <div class="flex justify-between items-start">
        <p class="text-xs font-bold text-slate-500">الكمية المصروفة للعمليات</p>
        <span class="text-[10px] bg-amber-100 text-amber-800 dark:bg-amber-950 dark:text-amber-300 px-2 py-0.5 rounded-full font-bold">📤 تشغيل ميداني</span>
      </div>
      <p class="text-3xl font-black text-amber-600 mt-1">${f.consumed} <span class="text-sm font-semibold text-slate-500">برميل</span></p>
      <p class="text-xs text-slate-400 mt-1">صرفت للسائقين بإشراف: عبدالقادر</p>
    </div>

    <div class="glass-card p-5 rounded-2xl border ${f.inWarehouse <= 5 ? 'border-rose-400 dark:border-rose-800 bg-rose-50/30' : 'border-slate-200 dark:border-slate-800'}">
      <div class="flex justify-between items-start">
        <p class="text-xs font-bold text-slate-500">الرصيد المتبقي بالمخزن</p>
        <span class="text-[10px] ${f.inWarehouse <= 5 ? 'bg-rose-100 text-rose-800 font-black' : 'bg-emerald-100 text-emerald-800 font-bold'} px-2 py-0.5 rounded-full">
          ${f.inWarehouse <= 5 ? '⚠️ رصيد منخفض' : '✓ رصيد متاح'}
        </span>
      </div>
      <p class="text-3xl font-black ${f.inWarehouse <= 5 ? 'text-rose-600' : 'text-emerald-600'} mt-1">${f.inWarehouse} <span class="text-sm font-semibold text-slate-500">برميل</span></p>
      <div class="w-full bg-slate-200 dark:bg-slate-700 h-2 rounded-full mt-2 overflow-hidden">
        <div class="${f.inWarehouse <= 5 ? 'bg-rose-500' : 'bg-emerald-600'} h-2 rounded-full transition-all duration-300" style="width: ${Math.min(remainingPercent, 100)}%"></div>
      </div>
    </div>
  `;

  if (fuelTable) {
    const transactions = (state.fuelTransactions || []).filter(tx => {
      if (filterType === 'purchase') return tx.type === 'purchase';
      if (filterType === 'issue') return tx.type === 'issue';
      return true;
    });

    if (transactions.length === 0) {
      fuelTable.innerHTML = `<tr><td colspan="7" class="text-center py-6 text-slate-400 text-xs">لا توجد حركات وقود مسجلة</td></tr>`;
      return;
    }

    fuelTable.innerHTML = transactions.map(tx => {
      const isPurchase = tx.type === 'purchase';
      return `
        <tr class="border-b border-slate-100 dark:border-slate-800 text-xs hover:bg-slate-50 dark:hover:bg-slate-800/40">
          <td class="py-3 px-4 font-mono font-medium">${tx.date}</td>
          <td class="py-3 px-4">
            <span class="px-2.5 py-0.5 rounded-full font-bold text-[11px] ${isPurchase ? 'bg-emerald-100 text-emerald-800 dark:bg-emerald-950 dark:text-emerald-300' : 'bg-amber-100 text-amber-800 dark:bg-amber-950 dark:text-amber-300'}">
              ${isPurchase ? '📥 توريد وشراء' : '📤 صرف تشغيل'}
            </span>
          </td>
          <td class="py-3 px-4 font-bold text-sm ${isPurchase ? 'text-emerald-700 dark:text-emerald-400' : 'text-amber-700 dark:text-amber-400'} font-mono">
            ${tx.quantity} برميل
          </td>
          <td class="py-3 px-4 font-medium text-slate-800 dark:text-slate-200">${tx.driver || '-'}</td>
          <td class="py-3 px-4 text-slate-600 dark:text-slate-400 font-semibold">${tx.plot || '-'}</td>
          <td class="py-3 px-4 text-slate-500 max-w-xs">
            <div>${tx.notes || tx.op || '-'}</div>
            <div class="text-[10px] text-slate-400 mt-0.5">المسؤول: <strong class="text-slate-600 dark:text-slate-300">${tx.loggedBy || 'عبدالقادر'}</strong></div>
          </td>
          <td class="py-3 px-4 text-left">
            <div class="flex items-center gap-1">
              <button onclick="openEditFuelTransactionModal('${tx.id}')" class="p-1.5 bg-slate-100 dark:bg-slate-800 hover:bg-emerald-50 hover:text-emerald-700 rounded-lg text-slate-500 transition" title="تعديل قيد الوقود">
                <i data-lucide="edit-3" class="w-3.5 h-3.5"></i>
              </button>
              <button onclick="deleteFuelTransaction('${tx.id}')" class="p-1.5 bg-slate-100 dark:bg-slate-800 hover:bg-rose-50 hover:text-rose-600 rounded-lg text-slate-400 transition" title="حذف القيد">
                <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>
              </button>
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }
}

// عرض المخزون الزراعي وسجل الحركات
function renderInventorySection() {
  const container = document.getElementById('inventory-cards-container');
  const tableBody = document.getElementById('inventory-transactions-table');
  const filterType = document.getElementById('inv-filter-type')?.value || 'all';

  recalculateInventoryTotals();

  if (container) {
    container.innerHTML = state.inventory.map(item => {
      const percentLeft = item.purchasedQty > 0 ? Math.round((item.remainingQty / item.purchasedQty) * 100) : 0;
      const isLowStock = item.remainingQty <= 2 && item.purchasedQty > 0;

      return `
        <div class="glass-card p-5 rounded-2xl border ${isLowStock ? 'border-amber-300 dark:border-amber-800' : 'border-slate-200 dark:border-slate-800'} flex flex-col justify-between">
          <div>
            <div class="flex justify-between items-start mb-2">
              <span class="text-xs font-bold px-2.5 py-0.5 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300">
                ${item.category}
              </span>
              <div class="flex items-center gap-1.5">
                <span class="text-[11px] font-semibold text-slate-400">${(item.unitPrice || 0).toLocaleString()} ج.س/${item.unit.split(' ')[0]}</span>
                <button onclick="openEditInventoryItemModal('${item.id}')" class="p-1 bg-slate-100 dark:bg-slate-800 hover:bg-emerald-100 dark:hover:bg-emerald-900 rounded-lg text-slate-500 hover:text-emerald-700 transition" title="تعديل الصنف">
                  <i data-lucide="edit-3" class="w-3 h-3"></i>
                </button>
              </div>
            </div>
            <h4 class="font-bold text-base text-slate-900 dark:text-white mb-2">${item.name}</h4>
            
            <div class="space-y-1.5 my-3 bg-slate-50 dark:bg-slate-800/50 p-3 rounded-xl text-xs">
              <div class="flex justify-between">
                <span class="text-slate-500">إجمالي المشتريات:</span>
                <span class="font-bold text-slate-800 dark:text-slate-200 font-mono">${item.purchasedQty} ${item.unit}</span>
              </div>
              <div class="flex justify-between">
                <span class="text-slate-500">الكمية المصروفة:</span>
                <span class="font-bold text-amber-600 font-mono">${item.usedQty} ${item.unit}</span>
              </div>
              <div class="flex justify-between border-t border-slate-200 dark:border-slate-700 pt-1">
                <span class="text-slate-700 dark:text-slate-300 font-bold">الرصيد المتبقي:</span>
                <span class="font-black ${isLowStock ? 'text-amber-600' : 'text-emerald-600'} font-mono">${item.remainingQty} ${item.unit}</span>
              </div>
            </div>

            <div class="w-full bg-slate-200 dark:bg-slate-700 h-1.5 rounded-full overflow-hidden">
              <div class="${isLowStock ? 'bg-amber-500' : 'bg-emerald-600'} h-1.5 rounded-full transition-all duration-300" style="width: ${Math.min(percentLeft, 100)}%"></div>
            </div>
          </div>

          <div class="flex gap-2 pt-3 mt-2 border-t border-slate-100 dark:border-slate-800">
            <button onclick="openAddInventoryStockModal('${item.id}')" class="flex-1 py-1.5 px-2 bg-emerald-50 dark:bg-emerald-950/60 hover:bg-emerald-600 hover:text-white text-emerald-800 dark:text-emerald-300 rounded-xl text-[11px] font-bold transition flex items-center justify-center gap-1">
              <i data-lucide="plus" class="w-3.5 h-3.5"></i>
              <span>توريد</span>
            </button>
            <button onclick="openIssueInventoryModal('${item.id}')" class="flex-1 py-1.5 px-2 bg-amber-50 dark:bg-amber-950/60 hover:bg-amber-600 hover:text-white text-amber-800 dark:text-amber-300 rounded-xl text-[11px] font-bold transition flex items-center justify-center gap-1">
              <i data-lucide="arrow-up-right" class="w-3.5 h-3.5"></i>
              <span>صرف</span>
            </button>
          </div>
        </div>
      `;
    }).join('');
  }

  if (tableBody) {
    const transactions = (state.inventoryTransactions || []).filter(tx => {
      if (filterType === 'purchase') return tx.type === 'purchase';
      if (filterType === 'issue') return tx.type === 'issue';
      return true;
    });

    if (transactions.length === 0) {
      tableBody.innerHTML = `<tr><td colspan="8" class="text-center py-6 text-slate-400 text-xs">لا توجد حركات مخزنية مسجلة</td></tr>`;
      return;
    }

    tableBody.innerHTML = transactions.map(tx => {
      const isPurchase = tx.type === 'purchase';
      return `
        <tr class="border-b border-slate-100 dark:border-slate-800 text-xs hover:bg-slate-50 dark:hover:bg-slate-800/40">
          <td class="py-3 px-4 font-mono font-medium">${tx.date}</td>
          <td class="py-3 px-4">
            <div class="font-bold text-slate-900 dark:text-white">${tx.itemName}</div>
            <span class="text-[10px] text-slate-400 font-semibold">${tx.category}</span>
          </td>
          <td class="py-3 px-4">
            <span class="px-2.5 py-0.5 rounded-full font-bold text-[11px] ${isPurchase ? 'bg-emerald-100 text-emerald-800 dark:bg-emerald-950 dark:text-emerald-300' : 'bg-amber-100 text-amber-800 dark:bg-amber-950 dark:text-amber-300'}">
              ${isPurchase ? '📥 توريد وشراء' : '📤 صرف للحقول'}
            </span>
          </td>
          <td class="py-3 px-4 font-bold text-sm font-mono ${isPurchase ? 'text-emerald-700 dark:text-emerald-400' : 'text-amber-700 dark:text-amber-400'}">
            ${tx.quantity} <span class="text-[11px] font-normal text-slate-500">${tx.unit}</span>
          </td>
          <td class="py-3 px-4 text-slate-700 dark:text-slate-300 font-semibold">${tx.plot || '-'}</td>
          <td class="py-3 px-4 text-slate-600 dark:text-slate-400">${tx.receiver || '-'}</td>
          <td class="py-3 px-4 text-slate-500 max-w-xs">
            <div>${tx.notes || '-'}</div>
            <div class="text-[10px] text-slate-400 mt-0.5">المسؤول: <strong class="text-slate-600 dark:text-slate-300">${tx.loggedBy || 'عبدالقادر'}</strong></div>
          </td>
          <td class="py-3 px-4 text-left">
            <div class="flex items-center gap-1">
              <button onclick="openEditFuelTransactionModal('${tx.id}')" class="p-1.5 bg-slate-100 dark:bg-slate-800 hover:bg-emerald-50 hover:text-emerald-700 rounded-lg text-slate-500 transition" title="تعديل">
                <i data-lucide="edit-3" class="w-3.5 h-3.5"></i>
              </button>
              <button onclick="deleteInventoryTransaction('${tx.id}')" class="p-1.5 bg-slate-100 dark:bg-slate-800 hover:bg-rose-50 hover:text-rose-600 rounded-lg text-slate-400 transition" title="حذف القيد">
                <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>
              </button>
            </div>
          </td>
        </tr>
      `;
    }).join('');
  }
}

// نافذة توريد وإضافة كمية للمخزون الزراعي
function openAddInventoryStockModal(preselectedId = null) {
  const selectedItem = preselectedId ? state.inventory.find(i => i.id === preselectedId) : (state.inventory[0] || null);

  const html = `
    <div class="p-6">
      <div class="flex justify-between items-center mb-4 border-b border-slate-200 dark:border-slate-800 pb-3">
        <div class="flex items-center gap-2">
          <span class="w-8 h-8 rounded-xl bg-emerald-100 text-emerald-800 flex items-center justify-center text-base font-bold">📥</span>
          <h3 class="text-base font-bold text-slate-900 dark:text-white">توريد وشراء مواد للمخزون الزراعي</h3>
        </div>
        <button onclick="closeModal()"><i data-lucide="x" class="w-5 h-5 text-slate-400"></i></button>
      </div>

      <form onsubmit="saveInventoryPurchase(event)" class="space-y-4 text-xs">
        <div>
          <label class="block font-bold mb-1">اختر الصنف الزراعي المراد توريده:</label>
          <select id="inv-buy-item" onchange="updateInventoryBuyDefaults()" class="w-full p-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 font-bold" required>
            ${state.inventory.map(i => `<option value="${i.id}" data-category="${i.category}" data-unit="${i.unit}" data-price="${i.unitPrice}" ${selectedItem && selectedItem.id === i.id ? 'selected' : ''}>${i.name} (${i.category}) - الرصيد الحالي: ${i.remainingQty} ${i.unit}</option>`).join('')}
          </select>
        </div>

        <div class="grid grid-cols-2 gap-3">
          <div>
            <label class="block font-bold mb-1">تاريخ التوريد:</label>
            <input type="date" id="inv-buy-date" value="${new Date().toISOString().split('T')[0]}" class="w-full p-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 font-mono font-bold" required>
          </div>
          <div>
            <label class="block font-bold mb-1">الكمية المشتراة:</label>
            <input type="number" step="0.5" id="inv-buy-qty" value="10" min="0.5" oninput="calculateInvCost()" class="w-full p-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 font-black text-emerald-600 text-sm" required>
          </div>
        </div>

        <div class="grid grid-cols-2 gap-3">
          <div>
            <label class="block font-bold mb-1">سعر شراء الوحدة (ج.س):</label>
            <input type="number" id="inv-buy-price" value="${selectedItem ? selectedItem.unitPrice : 38000}" min="0" oninput="calculateInvCost()" class="w-full p-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 font-mono font-bold" required>
          </div>
          <div>
            <label class="block font-bold mb-1">إجمالي الفاتورة (ج.س):</label>
            <input type="text" id="inv-buy-total" value="380,000 ج.س" readonly class="w-full p-2.5 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-100 dark:bg-slate-800 text-slate-800 dark:text-slate-200 font-black text-sm">
          </div>
        </div>

        <div class="grid grid-cols-2 gap-3">
          <div>
            <label class="block font-bold mb-1">المورد / المصدر:</label>
            <input type="text" id="inv-buy-supplier" placeholder="شركة التقاوي / التاجر" value="سوق القضارف العمومي" class="w-full p-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800" required>
          </div>
          <div>
            <label class="block font-bold mb-1">المستودع المستلم:</label>
            <input type="text" id="inv-buy-warehouse" value="المخزن الرئيسي للمزرعة" class="w-full p-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800">
          </div>
        </div>

        <div class="p-3 bg-emerald-50 dark:bg-emerald-950/40 rounded-xl border border-emerald-200 dark:border-emerald-900/50">
          <label class="flex items-center gap-2 cursor-pointer text-emerald-900 dark:text-emerald-200 font-bold">
            <input type="checkbox" id="inv-auto-expense" checked class="accent-emerald-600 rounded">
            <span>تسجيل قيد مالي فوري في سجل المصروفات</span>
          </label>
          <p class="text-[10px] text-emerald-700 dark:text-emerald-300 mt-1 pr-5">تحميل التكلفة فوراً على ميزانية المشروع تحت إشراف المدير المالي (مصطفى الجعلي).</p>
        </div>

        <div>
          <label class="block font-bold mb-1">ملاحظات / رقم الفاتورة:</label>
          <input type="text" id="inv-buy-notes" placeholder="رقم الفاتورة، مواصفات النقاوة..." class="w-full p-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800">
        </div>

        <div class="flex justify-end gap-2 pt-3 border-t border-slate-200 dark:border-slate-800">
          <button type="button" onclick="closeModal()" class="px-4 py-2 bg-slate-200 dark:bg-slate-700 rounded-xl font-bold">إلغاء</button>
          <button type="submit" class="px-5 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl font-bold">تأكيد التوريد وإضافة للمخزن</button>
        </div>
      </form>
    </div>
  `;
  openModal(html);
  calculateInvCost();
}

function updateInventoryBuyDefaults() {
  const select = document.getElementById('inv-buy-item');
  if (!select) return;
  const opt = select.options[select.selectedIndex];
  const price = opt.getAttribute('data-price') || 0;
  const priceInput = document.getElementById('inv-buy-price');
  if (priceInput) priceInput.value = price;
  calculateInvCost();
}

function calculateInvCost() {
  const qty = parseFloat(document.getElementById('inv-buy-qty')?.value) || 0;
  const price = parseFloat(document.getElementById('inv-buy-price')?.value) || 0;
  const total = qty * price;
  const el = document.getElementById('inv-buy-total');
  if (el) el.value = total.toLocaleString() + ' ج.س';
}

function saveInventoryPurchase(e) {
  e.preventDefault();

  const itemId = document.getElementById('inv-buy-item').value;
  const item = state.inventory.find(i => i.id === itemId);
  if (!item) return;

  const date = document.getElementById('inv-buy-date').value;
  const qty = parseFloat(document.getElementById('inv-buy-qty').value) || 0;
  const unitPrice = parseFloat(document.getElementById('inv-buy-price').value) || 0;
  const totalCost = qty * unitPrice;
  const supplier = document.getElementById('inv-buy-supplier').value.trim();
  const warehouse = document.getElementById('inv-buy-warehouse').value.trim();
  const autoExpense = document.getElementById('inv-auto-expense').checked;
  const notes = document.getElementById('inv-buy-notes').value.trim();

  const currentUserName = currentUser ? currentUser.name : "مصطفى الجعلي";

  const newTx = {
    id: `itx-${Date.now()}`,
    date,
    itemId: item.id,
    itemName: item.name,
    category: item.category,
    type: "purchase",
    quantity: qty,
    unit: item.unit,
    unitPrice,
    totalCost,
    plot: warehouse || "المخزن الرئيسي",
    crop: item.category === 'بذور' ? (item.name.includes('ذرة') ? 'ذرة' : 'تسالي') : 'مشترك',
    receiver: "-",
    loggedBy: currentUserName,
    notes: notes || `توريد وشراء ${qty} ${item.unit} من ${supplier} بإشراف عبدالقادر`
  };

  if (!state.inventoryTransactions) state.inventoryTransactions = [];
  state.inventoryTransactions.unshift(newTx);

  if (autoExpense && totalCost > 0) {
    state.expenses.unshift({
      id: `exp-${Date.now()}`,
      date,
      category: item.category === 'بذور' ? 'بذور' : (item.category === 'مبيدات' ? 'مبيدات' : (item.category === 'أسمدة' ? 'أسمدة' : 'مصاريف أخرى')),
      amount: totalCost,
      plot: "المخزن الرئيسي",
      crop: item.category === 'بذور' ? (item.name.includes('ذرة') ? 'ذرة' : 'تسالي') : 'مشترك',
      op: `شراء ${qty} ${item.unit} (${item.name})`,
      isUnderReview: false,
      createdBy: "مصطفى الجعلي",
      modifiedBy: null,
      notes: `فاتورة توريد: ${qty} ${item.unit} × ${unitPrice.toLocaleString()} ج.س (${supplier})`
    });
  }

  logAudit("توريد مخزون زراعي", `توريد ${qty} ${item.unit} من (${item.name}) بمبلغ ${totalCost.toLocaleString()} ج.س بإشراف عبدالقادر`, "المخزن الرئيسي");
  saveData();
  closeModal();
}

// نافذة صرف مواد من المخزون الزراعي للحقول
