function saveNewInventoryItem(e) {
  e.preventDefault();

  const name = document.getElementById('new-item-name').value.trim();
  const category = document.getElementById('new-item-category').value;
  const unit = document.getElementById('new-item-unit').value.trim();
  const initialQty = parseFloat(document.getElementById('new-item-initial-qty').value) || 0;
  const unitPrice = parseFloat(document.getElementById('new-item-price').value) || 0;

  const newItem = {
    id: `inv-${Date.now()}`,
    name,
    category,
    unit,
    purchasedQty: initialQty,
    usedQty: 0,
    remainingQty: initialQty,
    unitPrice
  };

  if (!state.inventory) state.inventory = [];
  state.inventory.push(newItem);

  logAudit("تعريف صنف جديد", `إضافة صنف جديد بالمخزن: (${name}) بوحدة (${unit})`, "المخزون الزراعي");
  saveData();
  closeModal();
}

function deleteInventoryTransaction(txId) {
  const tx = state.inventoryTransactions.find(t => t.id === txId);
  if (confirm(`هل أنت متأكد من حذف هذه الحركة المخزنية (${tx ? tx.itemName : ''})؟`)) {
    state.inventoryTransactions = state.inventoryTransactions.filter(t => t.id !== txId);
    if (tx) {
      logAudit("حذف حركة مخزنية", `حذف قيد حركة (${tx.type === 'purchase' ? 'توريد' : 'صرف'}) للصنف (${tx.itemName})`, tx.plot);
    }
    saveData();
  }
}

