function saveFuelStockPurchase(e) {
  e.preventDefault();

  const date = document.getElementById('fuel-buy-date').value;
  const qty = parseFloat(document.getElementById('fuel-buy-qty').value) || 0;
  const unitPrice = parseFloat(document.getElementById('fuel-buy-price').value) || 0;
  const totalCost = qty * unitPrice;
  const source = document.getElementById('fuel-buy-source').value.trim();
  const warehouse = document.getElementById('fuel-buy-warehouse').value.trim();
  const autoExpense = document.getElementById('fuel-auto-expense').checked;
  const notes = document.getElementById('fuel-buy-notes').value.trim();

  const currentUserName = currentUser ? currentUser.name : "مصطفى الجعلي";

  const newTx = {
    id: `ft-${Date.now()}`,
    date,
    type: "purchase",
    quantity: qty,
    driver: "-",
    plot: warehouse || "المخزن الرئيسي",
    op: `توريد وقود (${source})`,
    loggedBy: currentUserName,
    notes: notes || `توريد وشراء ${qty} برميل جاز بسعر ${unitPrice.toLocaleString()} ج.س/برميل بإشراف عبدالقادر`
  };

  if (!state.fuelTransactions) state.fuelTransactions = [];
  state.fuelTransactions.unshift(newTx);

  if (autoExpense && totalCost > 0) {
    state.expenses.unshift({
      id: `exp-${Date.now()}`,
      date,
      category: "وقود",
      amount: totalCost,
      plot: "المخزن الرئيسي",
      crop: "مشترك",
      op: `شراء ${qty} برميل جاز من ${source}`,
      isUnderReview: false,
      createdBy: "مصطفى الجعلي",
      modifiedBy: null,
      notes: `فاتورة توريد وقود: ${qty} برميل × ${unitPrice.toLocaleString()} ج.س (${notes || source})`
    });
  }

  logAudit("توريد وقود", `توريد ${qty} برميل جازولين للمخزن بمبلغ ${totalCost.toLocaleString()} ج.س بإشراف عبدالقادر`, "المخزن الرئيسي");
  saveData();
  closeModal();
}

