function saveFuelIssue(e) {
  e.preventDefault();

  const date = document.getElementById('fuel-issue-date').value;
  const qty = parseFloat(document.getElementById('fuel-issue-qty').value) || 0;
  const driver = document.getElementById('fuel-issue-driver').value;
  const plot = document.getElementById('fuel-issue-plot').value;
  const op = document.getElementById('fuel-issue-op').value;
  const notes = document.getElementById('fuel-issue-notes').value.trim();

  if (qty > state.fuelSummary.inWarehouse) {
    alert(`عذراً! الكمية المطلوبة (${qty} برميل) تتجاوز الرصيد المتبقي بالمخزن (${state.fuelSummary.inWarehouse} برميل).`);
    return;
  }

  const currentUserName = currentUser ? currentUser.name : "حسن مصطفى";

  const newTx = {
    id: `ft-${Date.now()}`,
    date,
    type: "issue",
    quantity: qty,
    driver,
    plot,
    op,
    loggedBy: currentUserName,
    notes: notes || `صرف ${qty} برميل للسائق ${driver} لعملية ${op} بإشراف عبدالقادر`
  };

  if (!state.fuelTransactions) state.fuelTransactions = [];
  state.fuelTransactions.unshift(newTx);

  logAudit("صرف وقود", `صرف ${qty} برميل جاز للسائق (${driver}) لتنفيذ (${op}) بمقطوعية (${plot}) بإشراف عبدالقادر`, plot);
  saveData();
  closeModal();
}

function deleteFuelTransaction(txId) {
  const tx = state.fuelTransactions.find(t => t.id === txId);
  if (confirm(`هل أنت متأكد من حذف حركة الوقود هذه (${tx ? tx.quantity + ' برميل' : ''})؟`)) {
    state.fuelTransactions = state.fuelTransactions.filter(t => t.id !== txId);
    if (tx) {
      logAudit("حذف حركة وقود", `حذف قيد حركة وقود (${tx.type === 'purchase' ? 'توريد' : 'صرف'}) بمقدار ${tx.quantity} برميل`, tx.plot);
    }
    saveData();
  }
}

// مسير رواتب العمالة والمشرفين مع نوع العامل وتاريخ المباشرة وتاريخ الانتهاء والاحتساب التلقائي
function renderLaborSection() {
  const laborTable = document.getElementById('labor-table-body');
  if (!laborTable) return;

  autoUpdateLaborWages();

  laborTable.innerHTML = state.labor.map(w => {
    const balance = (w.totalDue || 0) - (w.totalPaid || 0);
    let statusHtml = '';
    if (balance <= 0) {
      statusHtml = '<span class="badge-completed text-[11px] px-2.5 py-1 rounded-full font-bold">خالص بالكامل</span>';
    } else if (w.totalPaid > 0) {
      statusHtml = `<span class="badge-progress text-[11px] px-2.5 py-1 rounded-full font-bold">متبقي ${balance.toLocaleString()} ج.س</span>`;
    } else {
      statusHtml = `<span class="bg-rose-100 text-rose-800 text-[11px] px-2.5 py-1 rounded-full font-bold">غير مدفوع</span>`;
    }

    const isPermanent = (w.workerType !== 'temporary');
    const workerTypeBadge = isPermanent 
      ? '<span class="px-2.5 py-0.5 rounded-full text-[11px] font-bold bg-emerald-100 text-emerald-800 dark:bg-emerald-950 dark:text-emerald-300 border border-emerald-300">دائم</span>'
      : '<span class="px-2.5 py-0.5 rounded-full text-[11px] font-bold bg-amber-100 text-amber-800 dark:bg-amber-950 dark:text-amber-300 border border-amber-300">مؤقت / موسمي</span>';

    const days = w.daysWorked || Math.round((w.monthsWorked || 1) * 30);
    const endDateDisplay = w.endDate 
      ? `<div class="font-mono font-bold text-slate-800 dark:text-slate-200 bg-slate-100 dark:bg-slate-800 px-2 py-1 rounded-lg inline-block">${w.endDate}</div>`
      : '<span class="text-slate-400 font-semibold text-[11px]">مستمر (طوال الموسم)</span>';

    return `
      <tr class="border-b border-slate-100 dark:border-slate-800 text-xs hover:bg-slate-50 dark:hover:bg-slate-800/40">
        <td class="py-3.5 px-4 font-bold text-slate-900 dark:text-white">
          <div class="flex items-center gap-2">
            <span>👤 ${w.name}</span>
          </div>
          <div class="text-[10px] text-slate-400 font-normal mt-0.5">${w.plot ? `الموقع: ${w.plot}` : ''}</div>
        </td>
        <td class="py-3.5 px-4 text-slate-600 dark:text-slate-300 font-semibold">${w.role}</td>
        
        <!-- نوع العامل: دائم / مؤقت -->
        <td class="py-3.5 px-4">${workerTypeBadge}</td>

        <!-- تاريخ المباشرة -->
        <td class="py-3.5 px-4">
          <div class="font-mono font-bold text-slate-800 dark:text-slate-200 bg-slate-100 dark:bg-slate-800 px-2 py-1 rounded-lg inline-block">${w.startDate || 'غير محدد'}</div>
          ${w.startDate ? `<div class="text-[10px] text-emerald-600 dark:text-emerald-400 font-semibold mt-0.5">مباشر منذ ${days} يوم</div>` : ''}
        </td>

        <!-- تاريخ الانتهاء -->
        <td class="py-3.5 px-4">
          ${endDateDisplay}
        </td>

        <td class="py-3.5 px-4 font-mono font-bold text-emerald-700 dark:text-emerald-400">
          ${(w.monthlySalary || 0).toLocaleString()} <span class="text-[10px] text-slate-400 font-normal">ج.س/شهر</span>
        </td>

        <td class="py-3.5 px-4 font-mono font-bold text-slate-800 dark:text-slate-200">
          <div class="px-2.5 py-1 rounded-lg bg-slate-100 dark:bg-slate-800 font-bold inline-block">${w.monthsWorked || 1} شهر</div>
          <div class="text-[10px] text-slate-400 font-normal mt-0.5">${days} يوم عمل</div>
        </td>

        <!-- مسحوبات بقالة المشروع بالآجل -->
        <td class="py-3.5 px-4 font-mono font-bold">
          ${(w.groceryTotal && w.groceryTotal > 0) ? `
            <button onclick="openWorkerGroceryStatementModal('${w.id}')" class="px-2.5 py-1 bg-amber-50 dark:bg-amber-950/60 hover:bg-amber-100 border border-amber-300 dark:border-amber-700 text-amber-900 dark:text-amber-300 rounded-lg text-xs font-black transition flex items-center gap-1" title="عرض فواتير ومسحوبات البقالة التفصيلية">
              <span>🛒 ${(w.groceryTotal).toLocaleString()} ج.س</span>
            </button>
            <div class="text-[9px] text-amber-700 dark:text-amber-400 font-semibold mt-0.5">يخصم من المستحقات</div>
          ` : `
            <span class="text-slate-400 font-normal text-[11px]">- لا يوجد -</span>
          `}
        </td>

        <td class="py-3.5 px-4 font-bold text-slate-900 dark:text-white font-mono text-sm">
          <div>${(w.totalDue || 0).toLocaleString()} ج.س</div>
          <span class="text-[9px] text-emerald-600 dark:text-emerald-400 font-medium">⚡ صافي بعد خصم البقالة</span>
        </td>
        <td class="py-3.5 px-4 font-bold text-emerald-700 dark:text-emerald-400 font-mono">${(w.totalPaid || 0).toLocaleString()} ج.س</td>
        
        <td class="py-3.5 px-4">${statusHtml}</td>
        <td class="py-3.5 px-4 text-left">
          <div class="flex items-center gap-1.5">
            <button onclick="openWorkerSettlementVoucherModal('${w.id}')" class="px-2 py-1 bg-emerald-50 dark:bg-emerald-950/60 hover:bg-emerald-100 rounded-lg text-emerald-700 dark:text-emerald-300 font-bold transition flex items-center gap-1 text-[10px]" title="طباعة سند مخالصة وتصفية نهائية">
              <i data-lucide="file-check" class="w-3.5 h-3.5"></i>
              <span>سند مخالصة</span>
            </button>
            <button onclick="openAddGroceryTxModal('${w.id}')" class="p-1.5 bg-amber-50 dark:bg-amber-950/60 hover:bg-amber-100 rounded-lg text-amber-700 dark:text-amber-400 transition" title="تسجيل مشتريات وسحب بقالة جديد">
              <i data-lucide="shopping-cart" class="w-4 h-4"></i>
            </button>
            <button onclick="openEditLaborModal('${w.id}')" class="p-1.5 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 rounded-lg text-slate-600 transition" title="تعديل بيانات الراتب">
              <i data-lucide="edit-3" class="w-4 h-4"></i>
            </button>
            <button onclick="deleteLaborRecord('${w.id}')" class="p-1.5 bg-slate-100 dark:bg-slate-800 hover:bg-rose-50 hover:text-rose-600 rounded-lg text-slate-400 transition" title="حذف">
              <i data-lucide="trash-2" class="w-4 h-4"></i>
            </button>
          </div>
        </td>
      </tr>
    `;
  }).join('');
}

// ==========================================
// إدارة حسابات بقالة المشروع ومسحوبات العمالة الآجلة
// ==========================================
function renderGrocerySection() {
  const tableBody = document.getElementById('grocery-transactions-table');
  const kpiContainer = document.getElementById('grocery-status-cards');
  if (!tableBody) return;

  if (!state.groceryTransactions) state.groceryTransactions = [];

  // Populate worker filter dropdown if empty or has 1 option
  const filterSelect = document.getElementById('grocery-filter-worker');
  if (filterSelect && filterSelect.options.length <= 1) {
    const currentVal = filterSelect.value || 'all';
    filterSelect.innerHTML = '<option value="all">جميع العمال والمشرفين</option>' + 
      (state.labor || []).map(w => `<option value="${w.id}">${w.name} (${w.role})</option>`).join('');
    filterSelect.value = currentVal;
  }

  const workerFilter = filterSelect ? filterSelect.value : 'all';
  const searchInput = document.getElementById('grocery-search-input');
  const searchTerm = searchInput ? searchInput.value.trim().toLowerCase() : '';

  let filtered = state.groceryTransactions.slice();
  if (workerFilter !== 'all') {
    filtered = filtered.filter(t => t.workerId === workerFilter || t.workerName === workerFilter);
  }
  if (searchTerm) {
    filtered = filtered.filter(t => 
      (t.workerName || '').toLowerCase().includes(searchTerm) || 
      (t.items || '').toLowerCase().includes(searchTerm) || 
      (t.notes || '').toLowerCase().includes(searchTerm)
    );
  }

  // Calculate KPIs
  const totalGrocerySales = (state.groceryTransactions || []).reduce((sum, t) => sum + (parseFloat(t.amount) || 0), 0);
  const uniqueWorkersSet = new Set((state.groceryTransactions || []).map(t => t.workerId || t.workerName));
  const indebtedWorkersCount = uniqueWorkersSet.size;
  const totalTxCount = (state.groceryTransactions || []).length;

  if (kpiContainer) {
    kpiContainer.innerHTML = `
      <div class="glass-card p-4 rounded-2xl border border-amber-200 dark:border-amber-900/60 bg-amber-50/50 dark:bg-amber-950/30">
        <div class="flex items-center justify-between">
          <div>
            <p class="text-xs font-bold text-amber-800 dark:text-amber-300">إجمالي مسحوبات البقالة بالآجل</p>
            <h3 class="text-xl font-black text-amber-900 dark:text-amber-100 font-mono mt-1">${totalGrocerySales.toLocaleString()} ج.س</h3>
            <p class="text-[10px] text-amber-700 dark:text-amber-400 mt-0.5">تخصم تلقائياً من المستحقات النهائية للعمال</p>
          </div>
          <div class="w-10 h-10 rounded-xl bg-amber-500 text-white flex items-center justify-center font-bold text-lg shadow-md shadow-amber-500/20">
            🛒
          </div>
        </div>
      </div>

      <div class="glass-card p-4 rounded-2xl border border-slate-200 dark:border-slate-800">
        <div class="flex items-center justify-between">
          <div>
            <p class="text-xs font-bold text-slate-500 dark:text-slate-400">العمال المدينين لحساب البقالة</p>
            <h3 class="text-xl font-black text-slate-900 dark:text-white mt-1">${indebtedWorkersCount} <span class="text-xs font-normal text-slate-400">عمال</span></h3>
            <p class="text-[10px] text-slate-500 mt-0.5">لديهم مسحوبات إعاشة ومواد غذائية بالآجل</p>
          </div>
          <div class="w-10 h-10 rounded-xl bg-emerald-100 dark:bg-emerald-950 text-emerald-700 dark:text-emerald-300 flex items-center justify-center font-bold text-lg">
            👥
          </div>
        </div>
      </div>

      <div class="glass-card p-4 rounded-2xl border border-slate-200 dark:border-slate-800">
        <div class="flex items-center justify-between">
          <div>
            <p class="text-xs font-bold text-slate-500 dark:text-slate-400">عدد قيود وفواتير السحب</p>
            <h3 class="text-xl font-black text-slate-900 dark:text-white mt-1">${totalTxCount} <span class="text-xs font-normal text-slate-400">عملية</span></h3>
            <p class="text-[10px] text-slate-500 mt-0.5">مسجلة وموثقة في سجل بقالة الكمبو</p>
          </div>
          <div class="w-10 h-10 rounded-xl bg-blue-100 dark:bg-blue-950 text-blue-700 dark:text-blue-300 flex items-center justify-center font-bold text-lg">
            🧾
          </div>
        </div>
      </div>
    `;
  }

  if (filtered.length === 0) {
    tableBody.innerHTML = `
      <tr>
        <td colspan="7" class="text-center py-8 text-slate-400 text-xs font-bold">
          🛒 لا توجد مسحوبات بقالة مسجلة مطابقة لخيارات البحث
        </td>
      </tr>
    `;
    return;
  }

  tableBody.innerHTML = filtered.map(t => {
    return `
      <tr class="border-b border-slate-100 dark:border-slate-800 text-xs hover:bg-slate-50 dark:hover:bg-slate-800/40">
        <td class="py-3.5 px-4 font-mono font-bold text-slate-700 dark:text-slate-300">${t.date}</td>
        
        <td class="py-3.5 px-4 font-bold text-slate-900 dark:text-white">
          <div class="flex items-center gap-1.5">
            <span>👤 ${t.workerName}</span>
          </div>
        </td>

        <td class="py-3.5 px-4 text-slate-700 dark:text-slate-300 font-medium max-w-xs">
          <div class="line-clamp-2">${t.items || 'مواد إعاشة وسلع بقالة متنوعة'}</div>
        </td>

        <td class="py-3.5 px-4 font-mono font-black text-amber-700 dark:text-amber-400 text-sm">
          ${(parseFloat(t.amount) || 0).toLocaleString()} ج.س
        </td>

        <td class="py-3.5 px-4 text-slate-500 text-[11px] font-semibold">${t.loggedBy || 'عبدالقادر (الوكيل)'}</td>

        <td class="py-3.5 px-4">
          <span class="px-2.5 py-1 rounded-full text-[10px] font-bold bg-amber-100 text-amber-900 dark:bg-amber-950 dark:text-amber-300 border border-amber-300 flex items-center gap-1 w-max">
            <i data-lucide="check" class="w-3 h-3 text-amber-600"></i>
            <span>يخصم من المستحقات</span>
          </span>
        </td>

        <td class="py-3.5 px-4 text-left">
          <div class="flex items-center gap-1.5">
            <button onclick="openWorkerGroceryStatementModal('${t.workerId}')" class="p-1.5 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 rounded-lg text-slate-600 dark:text-slate-300 transition" title="عرض كشف حساب البقالة للعامل">
              <i data-lucide="file-text" class="w-4 h-4 text-emerald-600"></i>
            </button>
            <button onclick="openEditGroceryTxModal('${t.id}')" class="p-1.5 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 rounded-lg text-slate-600 transition" title="تعديل الفاتورة">
              <i data-lucide="edit-3" class="w-4 h-4"></i>
            </button>
            <button onclick="deleteGroceryTx('${t.id}')" class="p-1.5 bg-slate-100 dark:bg-slate-800 hover:bg-rose-50 hover:text-rose-600 rounded-lg text-slate-400 transition" title="حذف">
              <i data-lucide="trash-2" class="w-4 h-4"></i>
            </button>
          </div>
        </td>
      </tr>
    `;
  }).join('');
}

function openAddGroceryTxModal(preselectedWorkerId = null) {
  openEditGroceryTxModal(null, preselectedWorkerId);
}

function openEditGroceryTxModal(txId = null, preselectedWorkerId = null) {
  const isEdit = !!txId;
  const tx = isEdit ? state.groceryTransactions.find(t => t.id === txId) : {
    id: `groc-${Date.now()}`,
    date: new Date().toISOString().split('T')[0],
    workerId: preselectedWorkerId || (state.labor[0] ? state.labor[0].id : 'lab-1'),
    workerName: "",
    items: "سكر، شاي، صابون، زيت طعام",
    amount: 50000,
    loggedBy: currentUser ? currentUser.name : "عبدالقادر (الوكيل)",
    notes: "سحب بالآجل من بقالة الكمبو"
  };

  const html = `
    <div class="p-6">
      <div class="flex justify-between items-center mb-4 border-b border-slate-200 dark:border-slate-800 pb-3">
        <div class="flex items-center gap-2">
          <span class="w-8 h-8 rounded-xl bg-amber-100 dark:bg-amber-950 text-amber-800 dark:text-amber-300 flex items-center justify-center text-base font-bold">🛒</span>
          <h3 class="text-base font-black text-slate-900 dark:text-white">
            ${isEdit ? 'تعديل حركة سحب بقالة' : 'تسجيل مشتريات وسحب بقالة جديد بالآجل'}
          </h3>
        </div>
        <button onclick="closeModal()"><i data-lucide="x" class="w-5 h-5 text-slate-400"></i></button>
      </div>

      <form onsubmit="saveGroceryTx(event, '${tx.id}', ${isEdit})" class="space-y-4 text-xs">
        <div class="grid grid-cols-2 gap-3">
          <div>
            <label class="block font-bold mb-1">اسم العامل / الموظف المدين:</label>
            <select id="groc-worker-id" class="w-full p-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 font-bold" required>
              ${(state.labor || []).map(w => `
                <option value="${w.id}" ${(tx.workerId === w.id || tx.workerName === w.name) ? 'selected' : ''}>
                  ${w.name} (${w.role})
                </option>
              `).join('')}
            </select>
          </div>
          <div>
            <label class="block font-bold mb-1">تاريخ الشراء والسحب:</label>
            <input type="date" id="groc-date" value="${tx.date}" class="w-full p-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 font-bold font-mono" required>
          </div>
        </div>

        <div>
          <label class="block font-bold mb-1">تفاصيل الأصناف والمشتريات (مواد إعاشة وسلع):</label>
          <input type="text" id="groc-items" value="${tx.items || ''}" placeholder="مثال: سكر 10 رطل، شاي، صابون، زيت طعام، دقيق، بسكويت" class="w-full p-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 font-semibold" required>
          
          <!-- أزرار سريعة لإضافة أصناف شائعة -->
          <div class="flex flex-wrap gap-1.5 mt-2">
            <span class="text-[10px] text-slate-400 font-bold ml-1">أصناف شائعة:</span>
            <button type="button" onclick="appendGroceryItem('سكر (10 رطل)')" class="px-2 py-0.5 bg-slate-100 dark:bg-slate-800 hover:bg-amber-100 rounded-lg text-[10px] font-bold">+ سكر</button>
            <button type="button" onclick="appendGroceryItem('شاي كيني')" class="px-2 py-0.5 bg-slate-100 dark:bg-slate-800 hover:bg-amber-100 rounded-lg text-[10px] font-bold">+ شاي</button>
            <button type="button" onclick="appendGroceryItem('زيت طعام')" class="px-2 py-0.5 bg-slate-100 dark:bg-slate-800 hover:bg-amber-100 rounded-lg text-[10px] font-bold">+ زيت</button>
            <button type="button" onclick="appendGroceryItem('صابون غسيل وحمام')" class="px-2 py-0.5 bg-slate-100 dark:bg-slate-800 hover:bg-amber-100 rounded-lg text-[10px] font-bold">+ صابون</button>
            <button type="button" onclick="appendGroceryItem('بن قهوة وهيل')" class="px-2 py-0.5 bg-slate-100 dark:bg-slate-800 hover:bg-amber-100 rounded-lg text-[10px] font-bold">+ بن قهوة</button>
            <button type="button" onclick="appendGroceryItem('دقيق قمح')" class="px-2 py-0.5 bg-slate-100 dark:bg-slate-800 hover:bg-amber-100 rounded-lg text-[10px] font-bold">+ دقيق</button>
          </div>
        </div>

        <div class="p-3.5 bg-amber-50/70 dark:bg-amber-950/40 rounded-2xl border border-amber-200 dark:border-amber-900/50">
          <label class="block font-black text-amber-900 dark:text-amber-200 mb-1">💰 إجمالي مبلغ الفاتورة (جنيه سوداني):</label>
          <input type="number" id="groc-amount" value="${tx.amount || 0}" min="1" class="w-full p-2.5 rounded-xl border border-amber-300 dark:border-amber-700 bg-white dark:bg-slate-800 font-black font-mono text-amber-800 text-sm" required>
          <p class="text-[10px] text-amber-700 dark:text-amber-400 mt-1">يُخصم هذا المبلغ تلقائياً من رصيد مستحقات العامل في مسير الرواتب نهاية الموسم.</p>
        </div>

        <div>
          <label class="block font-bold mb-1">ملاحظات وبيان إضافي:</label>
          <input type="text" id="groc-notes" value="${tx.notes || ''}" placeholder="ملاحظات أو توثيق استلام" class="w-full p-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800">
        </div>

        <div class="flex justify-end gap-2 pt-3 border-t border-slate-200 dark:border-slate-800">
          <button type="button" onclick="closeModal()" class="px-4 py-2 bg-slate-200 dark:bg-slate-700 rounded-xl font-bold">إلغاء</button>
          <button type="submit" class="px-5 py-2 bg-amber-600 hover:bg-amber-700 text-white rounded-xl font-bold">حفظ قيد البقالة</button>
        </div>
      </form>
    </div>
  `;
  openModal(html);
}

function appendGroceryItem(itemText) {
  const input = document.getElementById('groc-items');
  if (input) {
    if (input.value.trim().length > 0) {
      input.value += '، ' + itemText;
    } else {
      input.value = itemText;
    }
  }
}

function saveGroceryTx(e, txId, isEdit) {
  e.preventDefault();

  const workerSelect = document.getElementById('groc-worker-id');
  const workerId = workerSelect.value;
  const workerObj = (state.labor || []).find(w => w.id === workerId);
  const workerName = workerObj ? workerObj.name : workerSelect.options[workerSelect.selectedIndex].text;

  const date = document.getElementById('groc-date').value;
  const items = document.getElementById('groc-items').value.trim();
  const amount = parseFloat(document.getElementById('groc-amount').value) || 0;
  const notes = document.getElementById('groc-notes').value.trim();
  const currentUserName = currentUser ? currentUser.name : "عبدالقادر (الوكيل)";

  if (!state.groceryTransactions) state.groceryTransactions = [];

  if (isEdit) {
    const idx = state.groceryTransactions.findIndex(t => t.id === txId);
    if (idx !== -1) {
      state.groceryTransactions[idx] = {
        ...state.groceryTransactions[idx],
        date, workerId, workerName, items, amount, notes,
        loggedBy: currentUserName
      };
      logAudit("تعديل سحب بقالة", `تحديث قيد مشتريات بقالة للعامل (${workerName}) بمبلغ ${amount.toLocaleString()} ج.س`, "بقالة المشروع");
    }
  } else {
    const newTx = {
      id: txId || `groc-${Date.now()}`,
      date,
      workerId,
      workerName,
      items,
      amount,
      loggedBy: currentUserName,
      notes: notes || "مسحوبات إعاشة من بقالة الكمبو"
    };
    state.groceryTransactions.unshift(newTx);
    logAudit("تسجيل سحب بقالة", `تسجيل سحب بالآجل للعامل (${workerName}) بمبلغ ${amount.toLocaleString()} ج.س (${items})`, "بقالة المشروع");
  }

  autoUpdateLaborWages();
  saveData("✓ تم حفظ قيد مشتريات البقالة وخصمها من مستحقات العامل بنجاح");
  closeModal();
}

function deleteGroceryTx(txId) {
  const tx = state.groceryTransactions.find(t => t.id === txId);
  if (confirm(`هل أنت متأكد من حذف قيد البقالة هذا للعامل (${tx ? tx.workerName : ''}) بمبلغ ${tx ? tx.amount.toLocaleString() : ''} ج.س؟`)) {
    state.groceryTransactions = state.groceryTransactions.filter(t => t.id !== txId);
    if (tx) {
      logAudit("حذف سحب بقالة", `حذف قيد مشتريات بقالة للعامل (${tx.workerName}) بمبلغ ${tx.amount.toLocaleString()} ج.س`, "بقالة المشروع");
    }
    autoUpdateLaborWages();
    saveData("✓ تم حذف قيد البقالة وتحديث مستحقات العامل بنجاح");
  }
}

