function renderAuditLogsSection() {
  const tableBody = document.getElementById('audit-logs-table-body');
  if (!tableBody) return;

  const logs = state.auditLogs || [];
  tableBody.innerHTML = logs.map(log => {
    let actionBadge = 'bg-slate-100 text-slate-700';
    if (log.actionType.includes('إضافة') || log.actionType.includes('توريد') || log.actionType.includes('اعتماد')) actionBadge = 'bg-emerald-100 text-emerald-800 font-bold';
    else if (log.actionType.includes('تعديل') || log.actionType.includes('صرف')) actionBadge = 'bg-amber-100 text-amber-800 font-bold';
    else if (log.actionType.includes('حذف')) actionBadge = 'bg-rose-100 text-rose-800 font-bold';
    else if (log.actionType.includes('وقود')) actionBadge = 'bg-blue-100 text-blue-800 font-bold';

    return `
      <tr class="border-b border-slate-100 dark:border-slate-800 text-xs hover:bg-slate-50 dark:hover:bg-slate-800/40">
        <td class="py-3 px-4 font-mono text-slate-500 dark:text-slate-400 whitespace-nowrap">${log.timestamp}</td>
        <td class="py-3 px-4 font-bold text-slate-900 dark:text-white">
          <div class="flex items-center gap-1.5">
            <span>👤 ${log.userName}</span>
            <span class="text-[10px] text-slate-400 font-normal">(${log.userRole})</span>
          </div>
        </td>
        <td class="py-3 px-4">
          <span class="px-2.5 py-0.5 rounded-full text-[11px] ${actionBadge}">
            ${log.actionType}
          </span>
        </td>
        <td class="py-3 px-4 font-semibold text-slate-800 dark:text-slate-200">${log.details}</td>
        <td class="py-3 px-4 text-slate-500 font-medium">${log.target}</td>
      </tr>
    `;
  }).join('');
}

