            <div class="p-2.5 bg-emerald-50 dark:bg-emerald-950/40 rounded-lg text-[11px] text-emerald-800 dark:text-emerald-200 font-medium">
              ✓ تم تأمين وتمويل حصة الشريك بالكامل في الموسم القادم 2027 بمبلغ <strong>${partnerNextSeasonShare.toLocaleString()} ج.س</strong> ذاتياً من أرباح مشروعه دون الحاجة لدفع أي مبالغ جديدة.
            </div>
