function saveOperation(e, plotId) {
  e.preventDefault();
  const plot = state.plots.find(p => p.id === plotId);
  if (!plot) return;

  const type = document.getElementById('op-type').value;
  const date = document.getElementById('op-date').value;
  const driver = document.getElementById('op-driver').value;
  const areaFeddan = parseFloat(document.getElementById('op-area').value) || plot.area;
  const fuel = parseFloat(document.getElementById('op-fuel').value) || 0;
  const status = document.getElementById('op-status').value;
  const notes = document.getElementById('op-notes').value;

  const fieldHours = calculateFieldHours(areaFeddan); // area / 5
  const userName = currentUser ? currentUser.name : "حسن مصطفى";

  const newOp = {
    id: `op-${Date.now()}`,
    type,
    date,
    driver,
    areaFeddan,
    fieldHours,
    fuelBarrels: fuel,
    status,
    notes: notes || "بإشراف عبدالقادر",
    createdBy: userName
  };

  plot.operations.push(newOp);

  // تحديث إنجاز الآلية وساعات تشغيل السائق في حال اكتمال العملية
  if (status === 'completed') {
    const machine = (state.machinery || []).find(m => m.driver && m.driver.includes(driver));
    if (machine) {
      machine.feddanDone = (machine.feddanDone || 0) + areaFeddan;
      machine.hoursOperated = (machine.hoursOperated || 0) + Math.round(fieldHours);
      if (fuel > 0) {
        machine.fuelUsedBarrels = (machine.fuelUsedBarrels || 0) + fuel;
      }
    }
  }

  if (status === 'completed' && fuel > 0) {
    state.fuelTransactions.push({
      id: `ft-${Date.now()}`,
      date,
      type: "issue",
      quantity: fuel,
      driver,
      plot: plot.name,
      op: `${type} (${areaFeddan} فدان - ${fieldHours} ساعة)`,
      loggedBy: userName,
      notes: notes || `صرف وقود لعملية ${type} (${areaFeddan} فدان @ 5 فدان/ساعة) بإشراف عبدالقادر`
    });
  }

  logAudit("تسجيل عملية زراعية", `إضافة عملية (${type}) لمقطوعية ${plot.name} بمساحة ${areaFeddan} فدان (${fieldHours} ساعة عمل) للسائق ${driver} بإشراف عبدالقادر`, plot.name);
  saveData();
  closeModal();
}

