function onLaborStartDateChange() {
  const startDateVal = document.getElementById('lab-start-date')?.value;
  const endDateVal = document.getElementById('lab-end-date')?.value;
  if (startDateVal) {
    let calcEnd = new Date();
    if (endDateVal) {
      const parsedEnd = new Date(endDateVal);
      if (!isNaN(parsedEnd.getTime())) {
        calcEnd = parsedEnd;
      }
    }
    const days = Math.max(1, getDaysDiff(startDateVal, calcEnd));
    const months = +(days / 30).toFixed(1);
    const monthsInput = document.getElementById('lab-months');
    if (monthsInput) {
      monthsInput.value = Math.max(0.1, months);
    }
  }
  recalculateModalTotals();
}

function recalculateModalTotals() {
  const months = parseFloat(document.getElementById('lab-months')?.value) || 1;
  const salary = parseFloat(document.getElementById('lab-monthly-salary')?.value) || 0;
  const overtime = parseFloat(document.getElementById('lab-overtime')?.value) || 0;
  const deductions = parseFloat(document.getElementById('lab-deductions')?.value) || 0;
  const paid = parseFloat(document.getElementById('lab-paid')?.value) || 0;

  const totalDue = Math.round(months * salary) + overtime - deductions;
  const balance = totalDue - paid;

  const elDue = document.getElementById('modal-lab-due');
  const elBal = document.getElementById('modal-lab-balance');

  if (elDue) elDue.innerText = totalDue.toLocaleString();
  if (elBal) elBal.innerText = balance.toLocaleString();
}

function saveLaborRecord(e, workerId, isEdit) {
  e.preventDefault();

  const name = document.getElementById('lab-name').value.trim();
  const role = document.getElementById('lab-role').value.trim();
  const workerType = document.getElementById('lab-worker-type').value;
  const startDate = document.getElementById('lab-start-date')?.value || '2026-07-01';
  const endDate = document.getElementById('lab-end-date')?.value || '';
  const monthsWorked = parseFloat(document.getElementById('lab-months').value) || 1;
  const monthlySalary = parseFloat(document.getElementById('lab-monthly-salary').value) || 0;
  const deductionsAmount = parseFloat(document.getElementById('lab-deductions').value) || 0;
  const overtime = parseFloat(document.getElementById('lab-overtime').value) || 0;
  const totalPaid = parseFloat(document.getElementById('lab-paid').value) || 0;

  const totalDue = Math.round(monthsWorked * monthlySalary) + overtime - deductionsAmount;
  const status = totalPaid >= totalDue ? 'paid' : (totalPaid > 0 ? 'partial' : 'pending');
  const updatedBy = currentUser ? currentUser.name : "حسن مصطفى";

  if (isEdit) {
    const idx = state.labor.findIndex(x => x.id === workerId);
    if (idx !== -1) {
      state.labor[idx] = {
        ...state.labor[idx],
        name, role, workerType, startDate, endDate, monthsWorked, monthlySalary, deductionsAmount, overtime, totalDue, totalPaid, status,
        lastUpdatedBy: updatedBy
      };
      logAudit("تعديل راتب شهري", `تحديث مسير راتب (${name} - ${workerType === 'permanent' ? 'دائم' : 'مؤقت'}) - ${monthsWorked} شهر × ${monthlySalary.toLocaleString()} ج.س = ${totalDue.toLocaleString()} ج.س`, "مسير الرواتب");
    }
  } else {
    const newWorker = {
      id: workerId,
      name,
      role,
      workerType,
      startDate,
      endDate,
      monthsWorked,
      monthlySalary,
      deductionsAmount,
      overtime,
      task: role,
      plot: "كامل المشروع",
      crop: "مشترك",
      areaFeddan: 0,
      totalDue,
      totalPaid,
      status,
      lastUpdatedBy: updatedBy
    };
    state.labor.push(newWorker);
    logAudit("إضافة عامل جديد", `إضافة (${name} - ${role} - ${workerType === 'permanent' ? 'دائم' : 'مؤقت'}) براتب شهري ${monthlySalary.toLocaleString()} ج.س`, "مسير الرواتب");
  }

  saveData("✓ تم حفظ بيانات مسير الراتب بنجاح");
  closeModal();
}

