function resetToInitialDefaults() {
  if (confirm("تحذير: هل أنت متأكد من إعادة ضبط قاعدة البيانات إلى القيم التأسيسية الافتراضية (182 قيداً و 14 برميل وقود)؟")) {
    if (confirm("تأكيد أخير: سيتم مسح أي تعديلات غير محفوظة خارج النسخة الافتراضية.")) {
      localStorage.removeItem(STORAGE_KEY);
      state = JSON.parse(JSON.stringify(DEFAULT_DATA));
      logAudit("إعادة ضبط", "استعادة البيانات التأسيسية للمشروع", "النظام العام");
      saveData("✓ تم استعادة النسخة التأسيسية الافتراضية لقاعدة البيانات");
      closeModal();
    }
  }
}

// ==========================================
// التصدير والطباعة
// ==========================================
function exportToCSV() {
  let csvContent = "data:text/csv;charset=utf-8,\uFEFF";
  csvContent += "التاريخ,البند,المبلغ (ج.س),المقطوعية,المحصول,الحالة,المسجل,البيان والملاحظات\n";

  state.expenses.forEach(e => {
    const row = `"${e.date}","${e.category}","${e.amount}","${e.plot || ''}","${e.crop || ''}","${e.isUnderReview ? 'للمراجعة' : 'معتمد'}","${e.createdBy || ''}","${(e.notes || e.op || '').replace(/"/g, '""')}"`;
    csvContent += row + "\n";
  });

  const encodedUri = encodeURI(csvContent);
  const link = document.createElement("a");
  link.setAttribute("href", encodedUri);
  link.setAttribute("download", `تقرير_مصروفات_مشروع_مصطفى_حسن_${new Date().toISOString().split('T')[0]}.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  showToast("✓ تم تصدير ملف الإكسيل بنجاح");
}

function printMonthlyReport() {
  window.print();
}

function backupJSON() {
  const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(state, null, 2));
  const downloadAnchor = document.createElement('a');
  downloadAnchor.setAttribute("href", dataStr);
  downloadAnchor.setAttribute("download", `قاعدة_بيانات_مشروع_مصطفى_حسن_${new Date().toISOString().split('T')[0]}.json`);
  document.body.appendChild(downloadAnchor);
  downloadAnchor.click();
  downloadAnchor.remove();
  showToast("✓ تم تنزيل النسخة الاحتياطية لقاعدة البيانات بنجاح");
}

function restoreJSON(event) {
  const file = event.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = function(e) {
    try {
      const parsed = JSON.parse(e.target.result);
      if (parsed && parsed.plots && parsed.expenses) {
        state = parsed;
        logAudit("استعادة نسخة", "استعادة نسخة احتياطية لقاعدة البيانات من ملف", "قاعدة البيانات");
        saveData("✓ تم استعادة قاعدة البيانات بنجاح من الملف المرفق");
        closeModal();
      } else {
        alert("الملف غير صالح أو لا يحتوي على بنية البيانات المتوافقة.");
      }
    } catch (err) {
      alert("حدث خطأ أثناء قراءة ملف النسخة الاحتياطية.");
    }
  };
  reader.readAsText(file);
}

