function switchDashboardHeroImage(imgKey) {
  const imgEl = document.getElementById('dashboard-hero-img');
  if (imgEl && GEDAREF_IMAGES[imgKey]) {
    imgEl.style.opacity = '0';
    setTimeout(() => {
      imgEl.src = GEDAREF_IMAGES[imgKey];
      imgEl.style.opacity = '0.65';
    }, 200);
  }
}

