// ========================================================
// وحدة الحصاد ومبيعات المحاصيل وتوريد زكاة الزروع (10%)
// ========================================================

function renderHarvestSection() {
  const intakes = state.harvestIntakes || [];
  const sales = state.cropSales || [];
  const zakat = state.zakatDeliveries || [];

  const totalIntakeBags = intakes.reduce((sum, h) => sum + (parseFloat(h.bags) || 0), 0);
  const totalSalesAmount = sales.reduce((sum, s) => sum + (parseFloat(s.totalAmount) || 0), 0);
  const totalPaidSales = sales.reduce((sum, s) => sum + (parseFloat(s.paidAmount) || 0), 0);
  const totalSoldBags = sales.reduce((sum, s) => sum + (parseFloat(s.bags) || 0), 0);
  const totalZakatBags = zakat.reduce((sum, z) => sum + (parseFloat(z.bags) || 0), 0);
  const remainingStockBags = Math.max(0, totalIntakeBags - totalSoldBags - totalZakatBags);

  // Render KPI cards
  const kpiEl = document.getElementById('harvest-kpi-container');
  if (kpiEl) {
    kpiEl.innerHTML = `
      <div class="glass-card p-4 rounded-2xl border border-emerald-200 dark:border-emerald-900 flex items-center gap-3">
        <div class="w-10 h-10 rounded-xl bg-emerald-100 dark:bg-emerald-950 text-emerald-700 dark:text-emerald-300 flex items-center justify-center font-black text-lg">🌾</div>
        <div>
          <p class="text-[11px] text-slate-500 font-bold">إجمالي المحصود (دخوليات):</p>
          <h4 class="text-base font-black text-slate-900 dark:text-white font-mono">${totalIntakeBags.toLocaleString()} <span class="text-xs">جوال</span></h4>
          <span class="text-[10px] text-emerald-600 font-bold">من نمر كسمور (1,450 فدان)</span>
        </div>
      </div>

      <div class="glass-card p-4 rounded-2xl border border-amber-200 dark:border-amber-900 flex items-center gap-3">
        <div class="w-10 h-10 rounded-xl bg-amber-100 dark:bg-amber-950 text-amber-700 dark:text-amber-300 flex items-center justify-center font-black text-lg">💰</div>
        <div>
          <p class="text-[11px] text-slate-500 font-bold">إجمالي المبيعات المحققة:</p>
          <h4 class="text-base font-black text-slate-900 dark:text-white font-mono">${totalSalesAmount.toLocaleString()} <span class="text-xs">ج.س</span></h4>
          <span class="text-[10px] text-amber-600 font-bold">محصل: ${totalPaidSales.toLocaleString()} ج.س</span>
        </div>
      </div>

      <div class="glass-card p-4 rounded-2xl border border-purple-200 dark:border-purple-900 flex items-center gap-3">
        <div class="w-10 h-10 rounded-xl bg-purple-100 dark:bg-purple-950 text-purple-700 dark:text-purple-300 flex items-center justify-center font-black text-lg">📜</div>
        <div>
          <p class="text-[11px] text-slate-500 font-bold">زكاة الزروع الموردة (10%):</p>
          <h4 class="text-base font-black text-slate-900 dark:text-white font-mono">${totalZakatBags.toLocaleString()} <span class="text-xs">جوال</span></h4>
          <span class="text-[10px] text-purple-600 font-bold">موردة لديوان الزكاة (إبراء ذمة)</span>
        </div>
      </div>

      <div class="glass-card p-4 rounded-2xl border border-blue-200 dark:border-blue-900 flex items-center gap-3">
        <div class="w-10 h-10 rounded-xl bg-blue-100 dark:bg-blue-950 text-blue-700 dark:text-blue-300 flex items-center justify-center font-black text-lg">🏢</div>
        <div>
          <p class="text-[11px] text-slate-500 font-bold">المخزون المتبقي (شونة/صوامع):</p>
          <h4 class="text-base font-black text-slate-900 dark:text-white font-mono">${remainingStockBags.toLocaleString()} <span class="text-xs">جوال</span></h4>
          <span class="text-[10px] text-blue-600 font-bold">متاح للبيع والتسويق</span>
        </div>
      </div>
    `;
  }

  // 1. Render Harvest Intakes Table
  const intakesBody = document.getElementById('harvest-intakes-table-body');
  if (intakesBody) {
    if (intakes.length === 0) {
      intakesBody.innerHTML = `<tr><td colspan="10" class="py-6 text-center text-slate-400">لا توجد دخوليات حصاد مسجلة حتى الآن. اضغط على «تسجيل دخولية حصاد» للإضافة.</td></tr>`;
    } else {
      intakesBody.innerHTML = intakes.map(h => {
        const isTasali = h.crop && h.crop.includes('تسالي');
        const bagUnitRate = isTasali ? '93 كجم/جوال' : '100 كجم/جوال';
        return `
        <tr class="hover:bg-slate-50/80 dark:hover:bg-slate-800/50 transition">
          <td class="py-3 px-4 font-mono font-bold text-slate-700 dark:text-slate-300">${h.date}</td>
          <td class="py-3 px-4 font-bold text-emerald-700 dark:text-emerald-400">📍 نمرة ${h.plot}</td>
          <td class="py-3 px-4 font-semibold">${h.crop}</td>
          <td class="py-3 px-4 font-mono font-black text-slate-900 dark:text-white text-sm">${(parseFloat(h.bags) || 0).toLocaleString()} جوال</td>
          <td class="py-3 px-4 font-mono">
            <span class="font-bold text-slate-800 dark:text-slate-200">${h.weightTons ? h.weightTons + ' طن' : '-'}</span>
            <span class="text-[10px] text-slate-400 block font-normal">${bagUnitRate}</span>
          </td>
          <td class="py-3 px-4 font-bold text-blue-700 dark:text-blue-400">${h.storageLocation || 'شونة الكمبو'}</td>
          <td class="py-3 px-4">${h.supervisor || 'عبدالقادر'}</td>
          <td class="py-3 px-4"><span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 text-emerald-800 dark:bg-emerald-950 dark:text-emerald-300">${h.qualityGrade || 'درجة أولى'}</span></td>
          <td class="py-3 px-4 text-slate-500 max-w-xs truncate">${h.notes || '-'}</td>
          <td class="py-3 px-4 text-left">
            <div class="flex items-center justify-end gap-1.5">
              <button onclick="openAddHarvestIntakeModal('${h.id}')" class="p-1.5 text-slate-600 hover:text-emerald-600 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700 transition" title="تعديل">
                <i data-lucide="edit-3" class="w-4 h-4"></i>
              </button>
              <button onclick="deleteHarvestIntake('${h.id}')" class="p-1.5 text-slate-400 hover:text-rose-600 rounded-lg hover:bg-rose-50 dark:hover:bg-rose-950 transition" title="حذف">
                <i data-lucide="trash-2" class="w-4 h-4"></i>
              </button>
            </div>
          </td>
        </tr>
      `;
      }).join('');
    }
  }

  // 2. Render Crop Sales Table
  const salesBody = document.getElementById('harvest-sales-table-body');
  if (salesBody) {
    if (sales.length === 0) {
      salesBody.innerHTML = `<tr><td colspan="11" class="py-6 text-center text-slate-400">لا توجد صفقات بيع مسجلة حتى الآن.</td></tr>`;
    } else {
      salesBody.innerHTML = sales.map(s => {
        const total = parseFloat(s.totalAmount) || 0;
        const paid = parseFloat(s.paidAmount) || 0;
        const rem = total - paid;
        return `
          <tr class="hover:bg-slate-50/80 dark:hover:bg-slate-800/50 transition">
            <td class="py-3 px-4 font-mono font-bold text-slate-700 dark:text-slate-300">${s.date}</td>
            <td class="py-3 px-4 font-black text-slate-900 dark:text-white">🏢 ${s.buyerName}</td>
            <td class="py-3 px-4 font-semibold">${s.crop}</td>
            <td class="py-3 px-4 font-mono font-bold">${(parseFloat(s.bags) || 0).toLocaleString()} جوال</td>
            <td class="py-3 px-4 font-mono">${(parseFloat(s.pricePerBag) || 0).toLocaleString()} ج.س</td>
            <td class="py-3 px-4 font-mono font-black text-slate-900 dark:text-white text-sm">${total.toLocaleString()} ج.س</td>
            <td class="py-3 px-4 font-mono font-bold text-emerald-600">${paid.toLocaleString()} ج.س</td>
            <td class="py-3 px-4 font-mono font-bold text-amber-600">${rem > 0 ? rem.toLocaleString() + ' ج.س' : '0'}</td>
            <td class="py-3 px-4">${s.paymentMethod || 'تحويل بنكك'}</td>
            <td class="py-3 px-4">
              <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${rem <= 0 ? 'bg-emerald-100 text-emerald-800 dark:bg-emerald-950 dark:text-emerald-300' : 'bg-amber-100 text-amber-800 dark:bg-amber-950 dark:text-amber-300'}">
                ${rem <= 0 ? '✓ مسدد بالكامل' : '⏳ متبقي رصيد'}
              </span>
            </td>
            <td class="py-3 px-4 text-left">
              <div class="flex items-center justify-end gap-1.5">
                <button onclick="openAddCropSaleModal('${s.id}')" class="p-1.5 text-slate-600 hover:text-amber-600 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700 transition" title="تعديل">
                  <i data-lucide="edit-3" class="w-4 h-4"></i>
                </button>
                <button onclick="deleteCropSale('${s.id}')" class="p-1.5 text-slate-400 hover:text-rose-600 rounded-lg hover:bg-rose-50 dark:hover:bg-rose-950 transition" title="حذف">
                  <i data-lucide="trash-2" class="w-4 h-4"></i>
                </button>
              </div>
            </td>
          </tr>
        `;
      }).join('');
    }
  }

  // 3. Render Zakat Deliveries Table
  const zakatBody = document.getElementById('harvest-zakat-table-body');
  if (zakatBody) {
    if (zakat.length === 0) {
      zakatBody.innerHTML = `<tr><td colspan="8" class="py-6 text-center text-slate-400">لا توجد توريدات زكاة مسجلة حتى الآن.</td></tr>`;
    } else {
      zakatBody.innerHTML = zakat.map(z => `
        <tr class="hover:bg-slate-50/80 dark:hover:bg-slate-800/50 transition">
          <td class="py-3 px-4 font-mono font-bold text-slate-700 dark:text-slate-300">${z.date}</td>
          <td class="py-3 px-4 font-bold text-purple-700 dark:text-purple-300">🌾 ${z.crop}</td>
          <td class="py-3 px-4 font-mono font-black text-slate-900 dark:text-white text-sm">${(parseFloat(z.bags) || 0).toLocaleString()} جوال</td>
          <td class="py-3 px-4 font-mono font-bold text-blue-700 dark:text-blue-400">#${z.receiptNo || '-'}</td>
          <td class="py-3 px-4 font-semibold">${z.recipientOrg || 'ديوان الزكاة - القضارف'}</td>
          <td class="py-3 px-4">${z.officialName || 'مفتش الزكاة'}</td>
          <td class="py-3 px-4 text-slate-500 max-w-xs truncate">${z.notes || '-'}</td>
          <td class="py-3 px-4 text-left">
            <div class="flex items-center justify-end gap-1.5">
              <button onclick="openAddZakatDeliveryModal('${z.id}')" class="p-1.5 text-slate-600 hover:text-purple-600 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700 transition" title="تعديل">
                <i data-lucide="edit-3" class="w-4 h-4"></i>
              </button>
              <button onclick="deleteZakatDelivery('${z.id}')" class="p-1.5 text-slate-400 hover:text-rose-600 rounded-lg hover:bg-rose-50 dark:hover:bg-rose-950 transition" title="حذف">
                <i data-lucide="trash-2" class="w-4 h-4"></i>
              </button>
            </div>
          </td>
        </tr>
      `).join('');
    }
  }
}

function switchHarvestSubTab(tabName) {
  const intakesView = document.getElementById('harvest-intakes-view');
  const salesView = document.getElementById('harvest-sales-view');
  const zakatView = document.getElementById('harvest-zakat-view');

  const btnIntakes = document.getElementById('tab-btn-harvest-intakes');
  const btnSales = document.getElementById('tab-btn-harvest-sales');
  const btnZakat = document.getElementById('tab-btn-harvest-zakat');

  [intakesView, salesView, zakatView].forEach(v => v && v.classList.add('hidden'));
  [btnIntakes, btnSales, btnZakat].forEach(b => b && b.classList.remove('bg-emerald-700', 'text-white', 'shadow-sm'));

  if (tabName === 'intakes') {
    if (intakesView) intakesView.classList.remove('hidden');
    if (btnIntakes) btnIntakes.classList.add('bg-emerald-700', 'text-white', 'shadow-sm');
  } else if (tabName === 'sales') {
    if (salesView) salesView.classList.remove('hidden');
    if (btnSales) btnSales.classList.add('bg-emerald-700', 'text-white', 'shadow-sm');
  } else if (tabName === 'zakat') {
    if (zakatView) zakatView.classList.remove('hidden');
    if (btnZakat) btnZakat.classList.add('bg-emerald-700', 'text-white', 'shadow-sm');
  }
  safeCreateIcons();
}

function calcHarvestWeightLive() {
  const crop = document.getElementById('harv-crop')?.value || '';
  const bags = parseFloat(document.getElementById('harv-bags')?.value) || 0;
  const isTasali = crop.includes('تسالي');
  const bagWeightKg = isTasali ? 93 : 100;
  const weightTons = +((bags * bagWeightKg) / 1000).toFixed(2);
  const totalKg = Math.round(bags * bagWeightKg);

  const displayEl = document.getElementById('harv-weight-display');
  if (displayEl) {
    displayEl.innerHTML = `
      <span class="text-slate-700 dark:text-slate-300 font-bold">الوزن التقديري المحسوب:</span>
      <span class="font-black text-emerald-700 dark:text-emerald-300 font-mono text-sm mr-1.5">${weightTons.toLocaleString()} طن</span>
      <span class="text-[11px] text-slate-500 font-medium">(${totalKg.toLocaleString()} كجم | بمعدل ${bagWeightKg} كجم/جوال)</span>
    `;
  }
}

