function saveHarvestIntake(e, intakeId) {
  e.preventDefault();
  const date = document.getElementById('harv-date').value;
  const plot = document.getElementById('harv-plot').value;
  const crop = document.getElementById('harv-crop').value;
  const bags = parseFloat(document.getElementById('harv-bags').value) || 0;
  const storageLocation = document.getElementById('harv-location').value;
  const supervisor = document.getElementById('harv-supervisor').value;
  const notes = document.getElementById('harv-notes').value.trim();
  
  // احتساب الوزن التقديري: 93 كجم لجوال التسالي، 100 كجم لجوال الذرة
  const isTasali = crop.includes('تسالي');
  const bagWeightKg = isTasali ? 93 : 100;
  const weightTons = +((bags * bagWeightKg) / 1000).toFixed(2);

  if (!state.harvestIntakes) state.harvestIntakes = [];

  if (intakeId) {
    const idx = state.harvestIntakes.findIndex(h => h.id === intakeId);
    if (idx !== -1) {
      state.harvestIntakes[idx] = {
        ...state.harvestIntakes[idx],
        date, plot, crop, bags, weightTons, storageLocation, supervisor, notes
      };
      logAudit("تعديل حصاد", `تعديل قيد دخولية حصاد نمرة ${plot} (${bags} جوال ${crop} = ${weightTons} طن) في ${storageLocation}`, "منظومة الحصاد");
    }
  } else {
    const newIntake = {
      id: `harv-${Date.now()}`,
      date, plot, crop, bags, weightTons, storageLocation, supervisor, qualityGrade: "درجة أولى", notes
    };
    state.harvestIntakes.unshift(newIntake);
    logAudit("تسجيل حصاد", `تسجيل دخولية حصاد جديدة من نمرة ${plot} (${bags} جوال ${crop} = ${weightTons} طن) لموقع ${storageLocation}`, "منظومة الحصاد");
    if (window.AgroAPI && window.AgroAPI.isConnected) {
      window.AgroAPI.insertHarvest(newIntake);
    }
  }

  // تحديث ومزامنة رصيد صنف المحصول في المخزون الزراعي
  if (!state.inventory) state.inventory = [];
  const cropCategory = crop.includes('ذرة') ? 'ذرة' : 'تسالي';
  let cropItem = state.inventory.find(i => (i.category === "محاصيل" || i.category === "غلال") && i.name.includes(cropCategory));
  if (!cropItem) {
    cropItem = {
      id: cropCategory === "ذرة" ? "inv-crop-sorghum" : "inv-crop-tasali",
      name: cropCategory === "ذرة" ? "محصول ذرة (مخزون الحصاد)" : "محصول تسالي (مخزون الحصاد)",
      category: "محاصيل",
      purchasedQty: bags,
      usedQty: 0,
      remainingQty: bags,
      unit: "جوال",
      unitPrice: cropCategory === "ذرة" ? 320000 : 450000
    };
    state.inventory.push(cropItem);
  }

  const totalIntakesForCrop = state.harvestIntakes.filter(h => h.crop && h.crop.includes(cropCategory)).reduce((sum, h) => sum + (parseFloat(h.bags) || 0), 0);
  cropItem.purchasedQty = totalIntakesForCrop;
  cropItem.remainingQty = Math.max(0, cropItem.purchasedQty - (cropItem.usedQty || 0));

  recalculateInventoryTotals();
  saveData("✓ تم حفظ وتحديث دخولية الحصاد ومزامنة المخزون بنجاح");
  closeModal();
}

function deleteHarvestIntake(intakeId) {
  const h = (state.harvestIntakes || []).find(x => x.id === intakeId);
  if (!h) return;

  if (confirm(`هل أنت متأكد من حذف قيد دخولية الحصاد (${h.bags} جوال من نمرة ${h.plot})؟`)) {
    state.harvestIntakes = (state.harvestIntakes || []).filter(x => x.id !== intakeId);
    
    // تحديث رصيد المخزون
    const cropCategory = h.crop && h.crop.includes('ذرة') ? 'ذرة' : 'تسالي';
    let cropItem = (state.inventory || []).find(i => (i.category === "محاصيل" || i.category === "غلال") && i.name.includes(cropCategory));
    if (cropItem) {
      const totalIntakesForCrop = state.harvestIntakes.filter(x => x.crop && x.crop.includes(cropCategory)).reduce((sum, x) => sum + (parseFloat(x.bags) || 0), 0);
      cropItem.purchasedQty = totalIntakesForCrop;
      cropItem.remainingQty = Math.max(0, cropItem.purchasedQty - (cropItem.usedQty || 0));
    }

    recalculateInventoryTotals();
    logAudit("حذف دخولية حصاد", `حذف قيد الحصاد من نمرة ${h.plot} (${h.bags} جوال)`, "منظومة الحصاد");
    saveData("✓ تم حذف قيد الحصاد وتحديث المخزون بنجاح");
    closeModal();
  }
}

function openAddCropSaleModal(saleId = null) {
  const item = saleId ? (state.cropSales || []).find(s => s.id === saleId) : null;
  const isEdit = !!item;

  const intakes = state.harvestIntakes || [];
  const sales = state.cropSales || [];
  const zakat = state.zakatDeliveries || [];

  const initialCrop = item ? item.crop : 'ذرة (طابت)';
  const cropCategory = initialCrop.includes('ذرة') ? 'ذرة' : 'تسالي';

  const intakeBagsForCrop = intakes.filter(h => h.crop && h.crop.includes(cropCategory)).reduce((sum, h) => sum + (parseFloat(h.bags) || 0), 0);
  const soldBagsForCrop = sales.filter(s => s.id !== saleId && s.crop && s.crop.includes(cropCategory)).reduce((sum, s) => sum + (parseFloat(s.bags) || 0), 0);
  const zakatBagsForCrop = zakat.filter(z => z.crop && z.crop.includes(cropCategory)).reduce((sum, z) => sum + (parseFloat(z.bags) || 0), 0);
  const availStockForCrop = Math.max(0, intakeBagsForCrop - soldBagsForCrop - zakatBagsForCrop);

  const initialBags = item ? item.bags : 100;
  const initialPrice = item ? item.pricePerBag : 320000;
  const initialTotal = initialBags * initialPrice;
  const initialPaid = item ? item.paidAmount : initialTotal;
  const initialRemaining = Math.max(0, initialTotal - initialPaid);

  const html = `
    <div class="p-6">
      <div class="flex justify-between items-center mb-4 border-b border-slate-200 dark:border-slate-800 pb-3">
        <div class="flex items-center gap-2">
          <span class="w-8 h-8 rounded-xl bg-amber-100 text-amber-800 flex items-center justify-center font-bold text-base">💰</span>
          <div>
            <h3 class="text-base font-bold text-slate-900 dark:text-white">${isEdit ? 'تعديل صفقة بيع محاصيل' : 'تسجيل عقد وصفقة بيع جديدة'}</h3>
            <p class="text-[10px] text-slate-400">تخصم الكمية المباعة تلقائياً من رصيد المخزون فور الحفظ</p>
          </div>
        </div>
        <button onclick="closeModal()"><i data-lucide="x" class="w-5 h-5 text-slate-400"></i></button>
      </div>

      <!-- بطاقة بيان المخزون المتاح للشحن -->
      <div class="p-3 bg-blue-50 dark:bg-blue-950/40 rounded-xl border border-blue-200 dark:border-blue-800 flex justify-between items-center text-xs mb-3">
        <div class="flex items-center gap-1.5">
          <span class="text-blue-600 dark:text-blue-400 font-bold">📦 رصيد المخزون المتاح للشحن والتسليم:</span>
          <span class="text-slate-500 font-semibold" id="sale-stock-crop-label">${initialCrop}</span>
        </div>
        <strong id="sale-available-stock-badge" class="font-mono text-blue-900 dark:text-blue-200 font-black text-sm">${availStockForCrop.toLocaleString()} جوال</strong>
      </div>

      <form onsubmit="saveCropSale(event, '${saleId || ''}')" class="space-y-4 text-xs">
        <div class="grid grid-cols-2 gap-3">
          <div>
            <label class="block font-bold mb-1">تاريخ الصفقة:</label>
            <input type="date" id="sale-date" value="${item ? item.date : new Date().toISOString().split('T')[0]}" class="w-full p-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 font-mono font-bold" required>
          </div>
          <div>
            <label class="block font-bold mb-1">اسم التاجر / الشركة المشترية:</label>
            <input type="text" id="sale-buyer" value="${item ? item.buyerName : ''}" placeholder="شركة البركة / التاجر أحمد ود النور..." class="w-full p-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 font-bold" required>
          </div>
        </div>

        <div class="grid grid-cols-3 gap-3">
          <div>
            <label class="block font-bold mb-1">المحصول المباع:</label>
            <select id="sale-crop" onchange="updateSaleCropStockBadge()" class="w-full p-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 font-bold" required>
              <option value="ذرة (طابت)" ${item && item.crop === 'ذرة (طابت)' ? 'selected' : ''}>ذرة (طابت)</option>
              <option value="ذرة (فتريتة)" ${item && item.crop === 'ذرة (فتريتة)' ? 'selected' : ''}>ذرة (فتريتة)</option>
              <option value="تسالي (حُميض)" ${item && item.crop === 'تسالي (حُميض)' ? 'selected' : ''}>تسالي (حُميض)</option>
              <option value="تسالي (بلدي)" ${item && item.crop === 'تسالي (بلدي)' ? 'selected' : ''}>تسالي (بلدي)</option>
            </select>
          </div>
          <div>
            <label class="block font-bold mb-1">الكمية المباعة (جوال):</label>
            <input type="number" id="sale-bags" value="${initialBags}" min="1" oninput="calcSaleTotalLive()" class="w-full p-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 font-mono font-bold" required>
          </div>
          <div>
            <label class="block font-bold mb-1">سعر الجوال (ج.س):</label>
            <input type="number" id="sale-price" value="${initialPrice}" min="1000" step="1000" oninput="calcSaleTotalLive()" class="w-full p-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 font-mono font-bold" required>
          </div>
        </div>

        <!-- إجمالي قيمة الصفقة المحتسبة -->
        <div class="p-3 bg-amber-50 dark:bg-amber-950/40 rounded-xl border border-amber-200 dark:border-amber-900 flex justify-between items-center font-bold">
          <span class="text-amber-900 dark:text-amber-200">إجمالي قيمة الصفقة (الكمية × السعر):</span>
          <span id="sale-total-display" class="font-mono text-base text-amber-700 dark:text-amber-300 font-black">${initialTotal.toLocaleString()} ج.س</span>
        </div>

        <!-- المبلغ المستلم والمبلغ المتبقي مع الاحتساب التلقائي -->
        <div class="space-y-2">
          <div class="flex justify-between items-center">
            <label class="block font-bold">المبلغ المستلم / المحصل (جنيه سوداني):</label>
            <div class="flex items-center gap-1 text-[10px]">
              <span class="text-slate-400 font-medium">سداد سريع:</span>
              <button type="button" onclick="setSalePaidPreset(1)" class="px-2 py-0.5 bg-emerald-100 hover:bg-emerald-200 text-emerald-800 rounded font-bold transition">100% كامل</button>
              <button type="button" onclick="setSalePaidPreset(0.5)" class="px-2 py-0.5 bg-blue-100 hover:bg-blue-200 text-blue-800 rounded font-bold transition">50% مقدم</button>
              <button type="button" onclick="setSalePaidPreset(0)" class="px-2 py-0.5 bg-slate-200 hover:bg-slate-300 text-slate-800 rounded font-bold transition">0% آجل</button>
            </div>
          </div>

          <div class="grid grid-cols-2 gap-3">
            <div>
              <input type="number" id="sale-paid" value="${initialPaid}" min="0" step="1000" oninput="calcSaleTotalLive()" class="w-full p-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 font-mono font-black text-emerald-600 text-sm" required>
            </div>
            <div>
              <select id="sale-method" class="w-full p-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 font-bold">
                <option value="تحويل بنكك" ${item && item.paymentMethod === 'تحويل بنكك' ? 'selected' : ''}>تحويل بنكك (حساب المشروع)</option>
                <option value="نقداً (كاش)" ${item && item.paymentMethod === 'نقداً (كاش)' ? 'selected' : ''}>نقداً (كاش بالخلا)</option>
                <option value="شيك مصرفي معتمد" ${item && item.paymentMethod === 'شيك مصرفي معتمد' ? 'selected' : ''}>شيك مصرفي معتمد</option>
                <option value="مقدم + متبقي مؤجل" ${item && item.paymentMethod === 'مقدم + متبقي مؤجل' ? 'selected' : ''}>مقدم + متبقي مؤجل</option>
              </select>
            </div>
          </div>
        </div>

        <!-- بطاقة الاحتساب التلقائي للمبلغ المتبقي -->
        <div id="sale-remaining-card" class="p-3 ${initialRemaining <= 0 ? 'bg-emerald-50 dark:bg-emerald-950/40 border-emerald-300 dark:border-emerald-800' : 'bg-rose-50 dark:bg-rose-950/40 border-rose-300 dark:border-rose-800'} rounded-xl border flex justify-between items-center font-bold transition">
          <div>
            <span class="text-[11px] text-slate-600 dark:text-slate-300 block">المبلغ المتبقي طرف المشتري (آجل):</span>
            <span id="sale-remaining-status-text" class="text-xs font-black ${initialRemaining <= 0 ? 'text-emerald-700 dark:text-emerald-300' : 'text-rose-700 dark:text-rose-300'}">
              ${initialRemaining <= 0 ? '✓ تم استلام وسداد كامل قيمة الصفقة نقداً / بنكك' : `⚠️ متبقي طرف التاجر: ${initialRemaining.toLocaleString()} ج.س`}
            </span>
          </div>
          <span id="sale-remaining-display" class="font-mono text-base ${initialRemaining <= 0 ? 'text-emerald-700 dark:text-emerald-300' : 'text-rose-700 dark:text-rose-300'} font-black">
            ${initialRemaining.toLocaleString()} ج.س
          </span>
        </div>

        <div>
          <label class="block font-bold mb-1">ملاحظات وموقع التسليم:</label>
          <input type="text" id="sale-notes" value="${item ? item.notes || '' : ''}" placeholder="تسليم صومعة القضارف، الشونة، أو بورصة المحاصيل..." class="w-full p-2.5 rounded-xl border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800">
        </div>

        <div class="flex justify-between items-center pt-3 border-t border-slate-200 dark:border-slate-800">
          ${isEdit ? `
            <button type="button" onclick="deleteCropSale('${saleId}')" class="px-3.5 py-2 bg-rose-50 hover:bg-rose-100 dark:bg-rose-950 text-rose-700 dark:text-rose-300 rounded-xl font-bold transition flex items-center gap-1.5 border border-rose-200 dark:border-rose-800">
              <i data-lucide="trash-2" class="w-4 h-4"></i>
              <span>حذف الصفقة</span>
            </button>
          ` : '<div></div>'}
          <div class="flex items-center gap-2">
            <button type="button" onclick="closeModal()" class="px-4 py-2 bg-slate-200 dark:bg-slate-700 rounded-xl font-bold">إلغاء</button>
            <button type="submit" class="px-5 py-2 bg-amber-600 hover:bg-amber-700 text-white rounded-xl font-bold">حفظ الصفقة وتحديث المخزون</button>
          </div>
        </div>
      </form>
    </div>
  `;
  openModal(html);
}

function calcSaleTotalLive() {
  const bags = parseFloat(document.getElementById('sale-bags')?.value) || 0;
  const price = parseFloat(document.getElementById('sale-price')?.value) || 0;
  const total = bags * price;

  const paidInput = document.getElementById('sale-paid');
  let paid = parseFloat(paidInput?.value);
  if (isNaN(paid)) paid = 0;

  const remaining = Math.max(0, total - paid);

  const totalDisplay = document.getElementById('sale-total-display');
  if (totalDisplay) totalDisplay.innerText = total.toLocaleString() + ' ج.س';

  const remDisplay = document.getElementById('sale-remaining-display');
  if (remDisplay) remDisplay.innerText = remaining.toLocaleString() + ' ج.س';

  const remCard = document.getElementById('sale-remaining-card');
  const remStatusText = document.getElementById('sale-remaining-status-text');
  if (remCard && remStatusText) {
    if (remaining <= 0) {
      remCard.className = 'p-3 bg-emerald-50 dark:bg-emerald-950/40 rounded-xl border border-emerald-300 dark:border-emerald-800 flex justify-between items-center font-bold transition';
      remStatusText.className = 'text-xs font-black text-emerald-700 dark:text-emerald-300';
      remStatusText.innerText = '✓ تم استلام وسداد كامل قيمة الصفقة نقداً / بنكك';
      if (remDisplay) remDisplay.className = 'font-mono text-base text-emerald-700 dark:text-emerald-300 font-black';
    } else {
      remCard.className = 'p-3 bg-rose-50 dark:bg-rose-950/40 rounded-xl border border-rose-300 dark:border-rose-800 flex justify-between items-center font-bold transition';
      remStatusText.className = 'text-xs font-black text-rose-700 dark:text-rose-300';
      remStatusText.innerText = `⚠️ متبقي طرف التاجر: ${remaining.toLocaleString()} ج.س`;
      if (remDisplay) remDisplay.className = 'font-mono text-base text-rose-700 dark:text-rose-300 font-black';
    }
  }
}

function setSalePaidPreset(ratio) {
  const bags = parseFloat(document.getElementById('sale-bags')?.value) || 0;
  const price = parseFloat(document.getElementById('sale-price')?.value) || 0;
  const total = bags * price;
  const paidInput = document.getElementById('sale-paid');
  if (paidInput) {
    paidInput.value = Math.round(total * ratio);
    calcSaleTotalLive();
  }
}

function updateSaleCropStockBadge() {
  const crop = document.getElementById('sale-crop')?.value || '';
  const cropCategory = crop.includes('ذرة') ? 'ذرة' : 'تسالي';
  const intakes = state.harvestIntakes || [];
  const sales = state.cropSales || [];
  const zakat = state.zakatDeliveries || [];

  const intakeBags = intakes.filter(h => h.crop && h.crop.includes(cropCategory)).reduce((sum, h) => sum + (parseFloat(h.bags) || 0), 0);
  const soldBags = sales.filter(s => s.crop && s.crop.includes(cropCategory)).reduce((sum, s) => sum + (parseFloat(s.bags) || 0), 0);
  const zakatBags = zakat.filter(z => z.crop && z.crop.includes(cropCategory)).reduce((sum, z) => sum + (parseFloat(z.bags) || 0), 0);
  const availStock = Math.max(0, intakeBags - soldBags - zakatBags);

  const label = document.getElementById('sale-stock-crop-label');
  const badge = document.getElementById('sale-available-stock-badge');
  if (label) label.innerText = crop;
  if (badge) badge.innerText = availStock.toLocaleString() + ' جوال';
}

function saveCropSale(e, saleId) {
  e.preventDefault();
  const date = document.getElementById('sale-date').value;
  const buyerName = document.getElementById('sale-buyer').value.trim();
  const crop = document.getElementById('sale-crop').value;
  const bags = parseFloat(document.getElementById('sale-bags').value) || 0;
  const pricePerBag = parseFloat(document.getElementById('sale-price').value) || 0;
  const totalAmount = bags * pricePerBag;
  const paidAmount = parseFloat(document.getElementById('sale-paid').value) || 0;
  const remainingAmount = Math.max(0, totalAmount - paidAmount);
  const paymentMethod = document.getElementById('sale-method').value;
  const notes = document.getElementById('sale-notes').value.trim();
  const status = remainingAmount <= 0 ? "مكتملة ومستلمة" : "مسدد جزئياً";
  const loggedBy = currentUser ? currentUser.name : "مصطفى الجعلي";

  if (!state.cropSales) state.cropSales = [];
  const targetSaleId = saleId || `sale-${Date.now()}`;

  if (saleId) {
    const idx = state.cropSales.findIndex(s => s.id === saleId);
    if (idx !== -1) {
      state.cropSales[idx] = {
        ...state.cropSales[idx],
        date, buyerName, crop, bags, pricePerBag, totalAmount, paidAmount, remainingAmount, paymentMethod, status, notes
      };
      logAudit("تعديل بيع محاصيل", `تحديث صفقة بيع ${buyerName} (${bags} جوال ${crop}) بقيمة ${totalAmount.toLocaleString()} ج.س (المستلم: ${paidAmount.toLocaleString()} ج.س | المتبقي: ${remainingAmount.toLocaleString()} ج.س)`, "تسويق المحاصيل");
    }
  } else {
    const newSale = {
      id: targetSaleId,
      date, buyerName, crop, bags, pricePerBag, totalAmount, paidAmount, remainingAmount, paymentMethod, deliveryLocation: "صومعة القضارف", status, loggedBy, notes
    };
    state.cropSales.unshift(newSale);
    logAudit("تسجيل بيع محاصيل", `تسجيل صفقة بيع جديدة للتاجر/الشركة ${buyerName} (${bags} جوال ${crop} بسعر ${pricePerBag.toLocaleString()} ج.س = ${totalAmount.toLocaleString()} ج.س | المستلم: ${paidAmount.toLocaleString()} ج.س | المتبقي: ${remainingAmount.toLocaleString()} ج.س)`, "تسويق المحاصيل");
    if (window.AgroAPI && window.AgroAPI.isConnected) {
      window.AgroAPI.insertSale(newSale);
    }
  }

  // مزامنة وخصم الكمية المباعة من المخزون الزراعي
  if (!state.inventory) state.inventory = [];
  if (!state.inventoryTransactions) state.inventoryTransactions = [];

  let cropItem = state.inventory.find(i => (i.category === "محاصيل" || i.category === "غلال") && i.name.includes(crop.includes("ذرة") ? "ذرة" : "تسالي"));
  if (!cropItem) {
    cropItem = {
      id: crop.includes("ذرة") ? "inv-crop-sorghum" : "inv-crop-tasali",
      name: crop.includes("ذرة") ? "محصول ذرة (مخزون الحصاد)" : "محصول تسالي (مخزون الحصاد)",
      category: "محاصيل",
      purchasedQty: crop.includes("ذرة") ? 3356 : 735,
      usedQty: 0,
      remainingQty: crop.includes("ذرة") ? 3356 : 735,
      unit: "جوال",
      unitPrice: pricePerBag
    };
    state.inventory.push(cropItem);
  }

  const txId = `itx-sale-${targetSaleId}`;
  const existingTxIdx = state.inventoryTransactions.findIndex(t => t.saleId === targetSaleId || t.id === txId);

  const invTx = {
    id: txId,
    saleId: targetSaleId,
    date,
    itemId: cropItem.id,
    itemName: cropItem.name,
    category: "محاصيل",
    type: "issue",
    quantity: bags,
    unit: "جوال",
    unitPrice: pricePerBag,
    totalCost: totalAmount,
    plot: notes || "صومعة القضارف / الشونة",
    crop: crop.includes("ذرة") ? "ذرة" : "تسالي",
    receiver: buyerName,
    loggedBy: loggedBy,
    notes: `صرف وتسليم مبيعات للتاجر/الشركة: ${buyerName} (${bags} جوال ${crop} × ${pricePerBag.toLocaleString()} ج.س)`
  };

  if (existingTxIdx !== -1) {
    state.inventoryTransactions[existingTxIdx] = invTx;
  } else {
    state.inventoryTransactions.unshift(invTx);
  }

  recalculateInventoryTotals();
  saveData(`✓ تم حفظ صفقة البيع بنجاح، وخصم (${bags} جوال) من المخزون، وتحديث المتبقي (${remainingAmount.toLocaleString()} ج.س)`);
  closeModal();
}

function deleteCropSale(saleId) {
  const s = (state.cropSales || []).find(x => x.id === saleId);
  if (!s) return;

  if (confirm(`هل أنت متأكد من حذف صفقة البيع للتاجر (${s.buyerName}) واستعادة الكمية المباعة (${s.bags} جوال) إلى المخزون؟`)) {
    state.cropSales = (state.cropSales || []).filter(x => x.id !== saleId);
    state.inventoryTransactions = (state.inventoryTransactions || []).filter(t => t.saleId !== saleId && t.id !== (`itx-sale-${saleId}`));
    
    recalculateInventoryTotals();
    logAudit("حذف صفقة بيع", `حذف صفقة بيع التاجر ${s.buyerName} واستعادة ${s.bags} جوال إلى المخزون`, "تسويق المحاصيل");
    saveData(`✓ تم حذف صفقة البيع واستعادة ${s.bags} جوال إلى رصيد المخزون بنجاح`);
    closeModal();
  }
}

