function saveMachine(e, machineId) {
  e.preventDefault();
  const name = document.getElementById('mac-name').value.trim();
  const type = document.getElementById('mac-type').value;
  const plate = document.getElementById('mac-plate').value.trim();
  const driver = document.getElementById('mac-driver').value.trim();
  const status = document.getElementById('mac-status').value;
  const hoursOperated = parseFloat(document.getElementById('mac-hours').value) || 0;
  const oilChangeDueHours = parseFloat(document.getElementById('mac-oil-due').value) || 0;

  if (!state.machinery) state.machinery = [];

  if (machineId) {
    const idx = state.machinery.findIndex(m => m.id === machineId);
    if (idx !== -1) {
      state.machinery[idx] = {
        ...state.machinery[idx],
        name, type, plate, driver, status, hoursOperated, oilChangeDueHours
      };
      logAudit("تعديل آلية", `تعديل بيانات الآلية ${name}`, "أسطول الآليات");
    }
  } else {
    const newMachine = {
      id: `mac-${Date.now()}`,
      name, type, plate, driver, status, hoursOperated, oilChangeDueHours, fuelTankCapacity: 160, feddanDone: 0, fuelUsedBarrels: 0
    };
    state.machinery.push(newMachine);
    logAudit("إضافة آلية", `إضافة الآلية ${name} لأسطول المزرعة`, "أسطول الآليات");
  }

  saveData("✓ تم حفظ بيانات الآلية بنجاح");
  closeModal();
}

function deleteMachine(machineId) {
  const m = (state.machinery || []).find(x => x.id === machineId);
  if (!m) return;

  if (confirm(`هل أنت متأكد من حذف الآلية (${m.name}) نهائياً من أسطول المشروع؟`)) {
    state.machinery = (state.machinery || []).filter(x => x.id !== machineId);
    logAudit("حذف آلية", `حذف الآلية ${m.name} (${m.type}) من أسطول المشروع`, "أسطول الآليات");
    saveData("✓ تم حذف الآلية من الأسطول بنجاح");
    closeModal();
  }
}

