function openPlotDetailsModal(plotId) {
  const plot = state.plots.find(p => p.id === plotId);
  if (!plot) return;

  const m = calculateMetrics();
  const plotExpenses = state.expenses.filter(e => e.plot === plot.name);
  const plotTotalSpent = plotExpenses.reduce((sum, e) => sum + (parseFloat(e.amount) || 0), 0);
  const plotIntakes = (state.harvestIntakes || []).filter(h => h.plot === plot.name);
  const plotTotalBags = plotIntakes.reduce((sum, h) => sum + (parseFloat(h.bags) || 0), 0);

  const html = `
    <div class="p-6 max-h-[85vh] overflow-y-auto">
      <div class="flex justify-between items-center mb-4 border-b border-slate-200 dark:border-slate-800 pb-3">
        <div class="flex items-center gap-2">
          <span class="w-8 h-8 rounded-xl bg-emerald-100 text-emerald-800 flex items-center justify-center font-black text-base">📍</span>
          <div>
            <h3 class="text-base font-black text-slate-900 dark:text-white">نمرة ${plot.name} (${plot.crop})</h3>
            <p class="text-[11px] text-slate-500">المساحة الإجمالية: ${plot.area} فدان • كسمور الشرقي</p>
          </div>
        </div>
        <button onclick="closeModal()"><i data-lucide="x" class="w-5 h-5 text-slate-400"></i></button>
      </div>

      <div class="space-y-4 text-xs">
        <div class="grid grid-cols-3 gap-3">
          <div class="p-3 bg-emerald-50 dark:bg-emerald-950/40 rounded-xl border border-emerald-200 dark:border-emerald-900">
            <p class="text-[10px] text-slate-500 font-bold">المساحة المزروعة:</p>
            <h4 class="text-sm font-black text-emerald-700 dark:text-emerald-300 font-mono">${plot.plantedFeddans || 0} من ${plot.area} فدان</h4>
          </div>
          <div class="p-3 bg-amber-50 dark:bg-amber-950/40 rounded-xl border border-amber-200 dark:border-amber-900">
            <p class="text-[10px] text-slate-500 font-bold">المصروف المباشر:</p>
            <h4 class="text-sm font-black text-amber-700 dark:text-amber-300 font-mono">${plotTotalSpent.toLocaleString()} ج.س</h4>
          </div>
          <div class="p-3 bg-blue-50 dark:bg-blue-950/40 rounded-xl border border-blue-200 dark:border-blue-900">
            <p class="text-[10px] text-slate-500 font-bold">المحصود الفعلي:</p>
            <h4 class="text-sm font-black text-blue-700 dark:text-blue-300 font-mono">${plotTotalBags.toLocaleString()} جوال</h4>
          </div>
        </div>

        <div>
          <h4 class="font-bold mb-2">العمليات الزراعية المنفذة بالنمرة:</h4>
          <div class="space-y-1.5 max-h-48 overflow-y-auto">
            ${(plot.operations || []).length === 0 ? '<p class="text-slate-400">لا توجد عمليات مسجلة.</p>' : (plot.operations || []).map(op => `
              <div class="p-2.5 bg-slate-50 dark:bg-slate-800/60 rounded-xl border border-slate-200 dark:border-slate-700 flex justify-between items-center">
                <div>
                  <span class="font-bold text-slate-900 dark:text-white">🚜 ${op.type}</span>
                  <span class="text-[10px] text-slate-500 mr-2">(${op.date} • السائق: ${op.driver || 'ابستة'})</span>
                </div>
                <span class="font-mono text-blue-600 font-bold">${op.fuelBarrels || 0} برميل وقود</span>
              </div>
            `).join('')}
          </div>
        </div>

        <div class="flex justify-end gap-2 pt-3 border-t border-slate-200 dark:border-slate-800">
          <button type="button" onclick="closeModal()" class="px-4 py-2 bg-slate-200 dark:bg-slate-700 rounded-xl font-bold">إغلاق</button>
          <button type="button" onclick="openAddOperationModal('${plot.id}');" class="px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl font-bold">+ تسجيل عملية</button>
        </div>
      </div>
    </div>
  `;
  openModal(html);
}

// =========================================================================
// وظائف الربط السحابي المشترك (Supabase PostgreSQL Cloud Integration)
// =========================================================================

function updateCloudStatusIndicator(isConnected, message) {
  const dot = document.getElementById('cloud-status-dot');
  const text = document.getElementById('cloud-status-text');
  const btn = document.getElementById('cloud-sync-badge-btn');
  if (!dot || !text || !btn) return;

  if (isConnected) {
    dot.className = 'w-2 h-2 rounded-full bg-emerald-400';
    text.textContent = '🟢 سحابي متصل';
    btn.className = 'inline-flex items-center gap-1.5 px-2.5 py-1.5 bg-emerald-800 hover:bg-emerald-900 text-white rounded-lg text-xs font-bold transition shadow-sm';
  } else {
    const rawCfg = localStorage.getItem('AGRO_SUPABASE_CLOUD_CONFIG');
    if (rawCfg) {
      dot.className = 'w-2 h-2 rounded-full bg-amber-400 animate-pulse';
      text.textContent = '🟡 وضع أوفلاين';
      btn.className = 'inline-flex items-center gap-1.5 px-2.5 py-1.5 bg-amber-800 hover:bg-amber-900 text-white rounded-lg text-xs font-bold transition shadow-sm';
    } else {
      dot.className = 'w-2 h-2 rounded-full bg-slate-400';
      text.textContent = '☁️ السحابة';
      btn.className = 'inline-flex items-center gap-1.5 px-2.5 py-1.5 bg-sky-700 hover:bg-sky-800 text-white rounded-lg text-xs font-bold transition shadow-sm';
    }
  }
}

